import React, { useState, useEffect, useRef } from 'react';
import { COLETANEA_DATA, CIAS_DATA } from '../utils/hymnData';

interface HymnRow {
  number: string;
  name: string;
}

interface HymnManagerProps {
  onBack: () => void;
}

const HymnManager: React.FC<HymnManagerProps> = ({ onBack }) => {
  // State
  const [activeRow, setActiveRow] = useState<number>(0);
  const [rows, setRows] = useState<HymnRow[]>(Array(8).fill({ number: '', name: '' }));
  const [fontSize, setFontSize] = useState<number>(22);
  const [searchQuery, setSearchQuery] = useState('');
  const [hymnType, setHymnType] = useState<'coletanea' | 'cias'>('coletanea');
  const [searchResults, setSearchResults] = useState<{number: string, name: string}[]>([]);

  // New state for "Louvor Após a Palavra" mode
  const [isAfterWordMode, setIsAfterWordMode] = useState(false);

  // New state for Preview and Loading
  const [generatedImageUrl, setGeneratedImageUrl] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);

  // Voice Recognition State
  const [isListening, setIsListening] = useState(false);
  const recognitionRef = useRef<any>(null);

  // Initialize Speech Recognition
  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;

    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.continuous = true;
      recognition.interimResults = true;
      recognition.lang = 'pt-BR';

      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);

      recognition.onerror = (event: any) => {
        console.error("Speech recognition error", event.error);
        setIsListening(false);
      };

      recognition.onresult = (event: any) => {
        let finalTranscript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) {
            finalTranscript += event.results[i][0].transcript;
          }
        }

        if (finalTranscript) {
            const cleanText = finalTranscript.replace(/[.]/g, '').toUpperCase();
            setSearchQuery(prev => {
                const spacer = prev && !prev.endsWith(' ') ? ' ' : '';
                return prev + spacer + cleanText;
            });
        }
      };

      recognitionRef.current = recognition;
    }
  }, []);

  const toggleListening = () => {
    if (!recognitionRef.current) {
        alert("Seu navegador não suporta reconhecimento de voz.");
        return;
    }
    if (isListening) {
        recognitionRef.current.stop();
    } else {
        setSearchQuery('');
        recognitionRef.current.start();
    }
  };

  // Search Logic
  useEffect(() => {
    if (!searchQuery.trim()) {
      setSearchResults([]);
      return;
    }
    const q = searchQuery.toLowerCase();
    const sourceDB = hymnType === 'coletanea' ? COLETANEA_DATA : CIAS_DATA;
    const results = sourceDB.filter(h => 
      h.number.toLowerCase().includes(q) || h.name.toLowerCase().includes(q)
    );
    setSearchResults(results.slice(0, 50));
  }, [searchQuery, hymnType]);

  const selectHymn = (hymn: { number: string, name: string }) => {
    let newRows = [...rows];
    newRows[activeRow] = { number: hymn.number, name: hymn.name.toUpperCase() };
    let nextRowIndex = activeRow + 1;
    if (activeRow === newRows.length - 1) {
      newRows.push({ number: '', name: '' });
    }
    setRows(newRows);
    setActiveRow(nextRowIndex);
    setSearchQuery('');
    setGeneratedImageUrl(null); // Clear preview when changing data
  };

  const activateAfterWordMode = () => {
    setIsAfterWordMode(true);
    setRows(Array(3).fill({ number: '', name: '' }));
    setActiveRow(0);
    setGeneratedImageUrl(null);
  };

  const activateStandardMode = () => {
    setIsAfterWordMode(false);
    setRows(Array(8).fill({ number: '', name: '' }));
    setActiveRow(0);
    setGeneratedImageUrl(null);
  };

  const handleMoveRow = (index: number, direction: 'up' | 'down') => {
    if (direction === 'up' && index > 0) {
      const newRows = [...rows];
      [newRows[index], newRows[index - 1]] = [newRows[index - 1], newRows[index]];
      setRows(newRows);
      if (activeRow === index) setActiveRow(index - 1);
      else if (activeRow === index - 1) setActiveRow(index);
    } 
    else if (direction === 'down') {
      if (index === rows.length - 1) {
        setRows(prev => [...prev, { number: '', name: '' }]);
        setActiveRow(index + 1);
      } else {
        const newRows = [...rows];
        [newRows[index], newRows[index + 1]] = [newRows[index + 1], newRows[index]];
        setRows(newRows);
        if (activeRow === index) setActiveRow(index + 1);
        else if (activeRow === index + 1) setActiveRow(index);
      }
    }
    setGeneratedImageUrl(null);
  };

  const clearList = () => {
    if (window.confirm("Deseja realmente limpar toda a lista?")) {
      const count = isAfterWordMode ? 3 : 8;
      setRows(Array(count).fill({ number: '', name: '' }));
      setActiveRow(0);
      setGeneratedImageUrl(null);
    }
  };

  const updateRow = (index: number, field: keyof HymnRow, value: string) => {
    const newRows = [...rows];
    newRows[index] = { ...newRows[index], [field]: value.toUpperCase() };
    setRows(newRows);
    setGeneratedImageUrl(null);
  };

  const currentDate = new Date().toLocaleDateString('pt-BR');

  const loadImage = (src: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => resolve(img);
      img.onerror = (e) => reject(e);
      img.src = src;
    });
  };

  const generateImage = async () => {
    setIsGenerating(true);
    // Pequeno delay para permitir que o UI mostre o estado de carregamento
    await new Promise(r => setTimeout(r, 300));

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) {
        setIsGenerating(false);
        return;
    }

    const contentWidth = 1200;
    const headerHeight = 100;
    const subHeaderHeight = 80;
    const rowHeight = 80;
    const totalContentHeight = headerHeight + subHeaderHeight + (rows.length * rowHeight) + 4;
    const pxPerMm = 5.7;
    const marginTop = Math.round(20 * pxPerMm);
    const marginSide = Math.round(7 * pxPerMm);
    const marginBottom = Math.round(7 * pxPerMm);

    canvas.width = contentWidth + (marginSide * 2);
    canvas.height = totalContentHeight + marginTop + marginBottom;

    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    const logoWidth = 36 * pxPerMm;
    const logoHeight = 12 * pxPerMm;
    const logoX = marginSide;
    const logoY = 4 * pxPerMm;

    try {
      const logoImg = await loadImage('/imagens/logoicm.png');
      ctx.drawImage(logoImg, logoX, logoY, logoWidth, logoHeight);
    } catch (error) {
      console.warn("Logo fallback.");
    }

    ctx.save();
    ctx.translate(marginSide, marginTop);

    const borderThickness = 5;
    const numColWidth = 180;

    ctx.fillStyle = '#000000';
    ctx.font = 'bold 45px Arial, sans-serif';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillText('LOUVORES', 30, headerHeight / 2);

    const today = new Date();
    const days = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];
    const dateStr = `${days[today.getDay()]} - ${today.toLocaleDateString('pt-BR')}`;

    if (isAfterWordMode) {
        ctx.textAlign = 'right';
        ctx.font = 'bold 24px Arial, sans-serif'; 
        ctx.fillText("LOUVOR APÓS A PALAVRA", contentWidth - 30, (headerHeight / 2) - 15);
        ctx.font = 'bold 28px Arial, sans-serif'; 
        ctx.fillText(dateStr, contentWidth - 30, (headerHeight / 2) + 20);
    } else {
        ctx.font = 'bold 32px Arial, sans-serif'; 
        ctx.textAlign = 'right';
        ctx.fillText(dateStr, contentWidth - 30, headerHeight / 2);
    }

    ctx.fillStyle = '#9ca3af';
    ctx.fillRect(0, headerHeight, contentWidth, subHeaderHeight);

    ctx.fillStyle = '#000000';
    ctx.font = 'bold 40px Arial, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Nº', numColWidth / 2, headerHeight + (subHeaderHeight / 2));
    ctx.fillText('Nome do Hino', numColWidth + ((contentWidth - numColWidth) / 2), headerHeight + (subHeaderHeight / 2));

    ctx.lineWidth = borderThickness;
    ctx.strokeStyle = '#000000';
    ctx.lineCap = 'square';

    let currentY = headerHeight + subHeaderHeight;

    rows.forEach((row, i) => {
        ctx.beginPath();
        ctx.moveTo(0, currentY);
        ctx.lineTo(contentWidth, currentY);
        ctx.stroke();

        const textY = currentY + (rowHeight / 2);
        const baseFontSize = 36;
        ctx.fillStyle = '#000000';

        if (row.number) {
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            const maxNumWidth = numColWidth - 20;
            let currentNumFontSize = baseFontSize;
            ctx.font = `bold ${currentNumFontSize}px Arial, sans-serif`;
            const numTextWidth = ctx.measureText(row.number).width;
            if (numTextWidth > maxNumWidth) {
                const ratio = maxNumWidth / numTextWidth;
                currentNumFontSize = Math.floor(baseFontSize * ratio);
                ctx.font = `bold ${currentNumFontSize}px Arial, sans-serif`;
            }
            ctx.fillText(row.number, numColWidth / 2, textY);
        }

        if (row.name) {
            ctx.textAlign = 'left';
            ctx.textBaseline = 'middle';
            const nameX = numColWidth + 30;
            const maxNameWidth = contentWidth - numColWidth - 45;
            let currentFontSize = baseFontSize;
            ctx.font = `bold ${currentFontSize}px Arial, sans-serif`;
            const textWidth = ctx.measureText(row.name).width;
            if (textWidth > maxNameWidth) {
                const ratio = maxNameWidth / textWidth;
                currentFontSize = Math.floor(baseFontSize * ratio);
                ctx.font = `bold ${currentFontSize}px Arial, sans-serif`;
            }
            ctx.fillText(row.name, nameX, textY);
        }
        currentY += rowHeight;
    });

    ctx.beginPath();
    ctx.moveTo(numColWidth, headerHeight); 
    ctx.lineTo(numColWidth, totalContentHeight); 
    ctx.stroke();
    ctx.strokeRect(0, 0, contentWidth, totalContentHeight);
    ctx.beginPath();
    ctx.moveTo(0, headerHeight);
    ctx.lineTo(contentWidth, headerHeight);
    ctx.stroke();

    ctx.restore();

    const dataUrl = canvas.toDataURL('image/png');
    setGeneratedImageUrl(dataUrl);
    setIsGenerating(false);

    setTimeout(() => {
      const previewEl = document.getElementById('preview-section');
      previewEl?.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  };

  const downloadImage = () => {
    if (!generatedImageUrl) return;
    const link = document.createElement('a');
    const today = new Date();
    const prefix = isAfterWordMode ? 'louvor-apos-palavra' : 'louvores';
    link.download = `${prefix}-${today.toLocaleDateString('pt-BR').replace(/\//g, '-')}.png`;
    link.href = generatedImageUrl;
    link.click();
  };

  const shareToWhatsapp = async () => {
    if (!generatedImageUrl) return;
    try {
      const res = await fetch(generatedImageUrl);
      const blob = await res.blob();
      const file = new File([blob], "louvores.png", { type: "image/png" });

      if (navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({
          files: [file],
          title: 'Lista de Louvores',
          text: 'Segue a lista de louvores do culto.'
        });
      } else {
        alert("O compartilhamento direto de imagem não é suportado neste navegador. Por favor, baixe a imagem.");
      }
    } catch (error) {
      console.error("Error sharing:", error);
      alert("Erro ao compartilhar. Tente baixar a imagem.");
    }
  };

  const pageTitle = isAfterWordMode ? "Louvor Após a Palavra" : "Lista de Louvores";

  return (
    <div className="min-h-screen bg-[#ffeeefff] font-sans flex flex-col items-center pt-8 pb-8 px-4">

      <h1 className="text-3xl font-bold text-[#a62626] mb-6 drop-shadow-sm text-center uppercase">{pageTitle}</h1>

      {!isAfterWordMode ? (
        <button 
          onClick={activateAfterWordMode}
          className="bg-[#dc2626] hover:bg-[#b91c1c] text-white font-bold py-2 px-6 rounded-md shadow-md hover:shadow-lg mb-8 uppercase text-sm tracking-wide transition-all"
        >
          Ir para Louvor Após a Palavra
        </button>
      ) : (
         <button 
          onClick={activateStandardMode}
          className="bg-white hover:bg-gray-50 text-[#a62626] border border-[#dc2626] font-bold py-2 px-6 rounded-md shadow-md hover:shadow-lg mb-8 uppercase text-sm tracking-wide transition-all"
        >
          Voltar para Lista Completa
        </button>
      )}

      <div className="bg-white rounded-3xl shadow-xl w-full max-w-4xl p-6 md:p-8 relative">
        <div className="text-center mb-6">
          <h2 className="text-[#a62626] text-xl font-bold uppercase tracking-wider mb-2">{isAfterWordMode ? "Louvor Após a Palavra" : "Louvores"}</h2>
          <p className="text-[#b91c1c] font-medium">Data: {currentDate}</p>
        </div>

        <div className="border border-red-100 rounded-xl p-4 mb-6 bg-red-50/30">
          <div className="flex items-center gap-2 mb-3 text-[#a62626] font-bold text-sm">
             <i className="fas fa-file-lines"></i>
             <span>Buscar Louvores</span>
          </div>

          <p className="text-[#a62626] text-xs font-semibold mb-2">Selecione o tipo de louvor:</p>
          <div className="flex gap-4 mb-4 text-sm text-[#7f1d1d]">
             <label className="flex items-center gap-2 cursor-pointer">
               <input type="radio" name="type" checked={hymnType === 'coletanea'} onChange={() => setHymnType('coletanea')} className="accent-blue-500" />
               Louvores de Coletânea
             </label>
             <label className="flex items-center gap-2 cursor-pointer">
               <input type="radio" name="type" checked={hymnType === 'cias'} onChange={() => setHymnType('cias')} className="accent-blue-500" />
               Louvores das Cias
             </label>
          </div>

          <div className="relative">
            <div className="relative">
              <i className="fas fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-gray-500"></i>
              <input 
                type="text" 
                placeholder="DIGITE OU USE O MICROFONE..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
                className="w-full pl-9 pr-12 py-3 border border-red-200 rounded-md focus:outline-none focus:border-red-400 text-sm text-black bg-white uppercase shadow-sm placeholder-gray-400"
              />
              <button
                onClick={toggleListening}
                className={`absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 rounded-full flex items-center justify-center transition-all ${isListening ? 'bg-red-600 text-white animate-pulse shadow-lg' : 'text-gray-400 hover:text-red-500 hover:bg-red-50'}`}
                title={isListening ? "Parar de ouvir" : "Falar nome ou número"}
              >
                 <i className={`fas fa-microphone${isListening ? '' : '-slash text-xs'} text-sm`}></i>
              </button>
            </div>

            {searchResults.length > 0 && (
              <div className="absolute top-full left-0 right-0 bg-white border border-gray-200 rounded-md shadow-lg mt-1 z-10 max-h-48 overflow-y-auto">
                {searchResults.map((h, i) => (
                   <button 
                    key={i}
                    onClick={() => selectHymn(h)}
                    className="w-full text-left px-4 py-2 text-sm text-black bg-white hover:bg-red-50 flex justify-between border-b last:border-0 border-gray-100 uppercase"
                   >
                     <span>{h.name}</span>
                     <span className="font-bold text-red-500">{h.number}</span>
                   </button>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="flex justify-center mb-4">
          <button onClick={clearList} className="bg-[#fecdd3] hover:bg-[#fda4af] text-[#9f1239] px-4 py-2 rounded-md text-sm font-semibold flex items-center gap-2 transition-colors shadow-sm hover:shadow-md">
            <i className="fas fa-trash-can"></i>
            Limpar Lista
          </button>
        </div>

        <div className="border border-slate-300 rounded-sm overflow-hidden bg-white">
           <div className="flex bg-white border-b border-slate-300 h-8 items-center text-[#a62626] text-xs font-bold text-center">
              <div className="w-8 border-r border-slate-300 h-full flex items-center justify-center bg-slate-100"></div>
              <div className="w-12 border-r border-slate-300 h-full flex items-center justify-center">Nº</div>
              <div className="flex-1 h-full flex items-center justify-center">Nome do Hino</div>
           </div>

           {rows.map((row, idx) => (
             <div 
               key={idx} 
               onClick={() => setActiveRow(idx)}
               className={`flex h-9 border-b border-slate-300 last:border-0 items-center text-sm ${activeRow === idx ? 'bg-blue-50' : 'bg-white'}`}
             >
                <div className="w-8 border-r border-slate-300 h-full flex flex-col items-center justify-center gap-[1px] bg-slate-50">
                  <button onClick={(e) => {e.stopPropagation(); handleMoveRow(idx, 'up')}} className="text-[8px] text-slate-400 hover:text-blue-500 leading-none"><i className="fas fa-chevron-up"></i></button>
                  <button onClick={(e) => {e.stopPropagation(); handleMoveRow(idx, 'down')}} className="text-[8px] text-slate-400 hover:text-blue-500 leading-none"><i className="fas fa-chevron-down"></i></button>
                </div>

                <div className="w-12 border-r border-slate-300 h-full p-1 bg-white">
                  <input 
                    type="text" 
                    value={row.number}
                    onChange={(e) => updateRow(idx, 'number', e.target.value)}
                    className="w-full h-full text-center outline-none bg-white text-black font-bold"
                  />
                </div>

                <div className="flex-1 h-full p-1 bg-white">
                  <input 
                    type="text" 
                    value={row.name}
                    onChange={(e) => updateRow(idx, 'name', e.target.value)}
                    className="w-full h-full px-2 outline-none bg-white text-black uppercase"
                  />
                </div>
             </div>
           ))}
        </div>
      </div>

      <div className="w-full max-w-4xl mt-6 flex flex-col gap-6">
         <button 
           onClick={generateImage}
           disabled={isGenerating}
           className={`w-full font-bold py-4 rounded-lg shadow-lg flex items-center justify-center gap-2 transition-all transform hover:-translate-y-0.5 ${isGenerating ? 'bg-gray-400 cursor-not-allowed' : 'bg-[#dc2626] hover:bg-[#b91c1c] text-white shadow-red-500/20'}`}
         >
            {isGenerating ? (
               <>
                 <i className="fas fa-spinner animate-spin"></i>
                 Processando Imagem...
               </>
            ) : (
               <>
                 <i className="fas fa-image"></i>
                 GERAR CARTAZ FINAL
               </>
            )}
         </button>

         {generatedImageUrl && (
           <div id="preview-section" className="bg-white rounded-3xl shadow-2xl p-6 md:p-8 animate-in fade-in zoom-in duration-500 border-2 border-red-50">
               <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                  <div className="text-center md:text-left">
                    <h3 className="text-[#a62626] font-bold text-2xl flex items-center gap-2 justify-center md:justify-start">
                       <i className="fas fa-magnifying-glass-chart"></i>
                       Conferência da Imagem
                    </h3>
                    <p className="text-gray-500 text-sm italic">Verifique se os hinos e números estão corretos antes de compartilhar.</p>
                  </div>

                  <div className="flex gap-2">
                    <button 
                        onClick={generateImage}
                        className="bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2 rounded-full text-sm font-bold flex items-center gap-2 transition-colors"
                    >
                        <i className="fas fa-arrows-rotate"></i>
                        Atualizar
                    </button>
                    <button 
                        onClick={() => setGeneratedImageUrl(null)} 
                        className="w-10 h-10 bg-red-100 rounded-full text-red-500 flex items-center justify-center hover:bg-red-200 transition-colors"
                    >
                        <i className="fas fa-times"></i>
                    </button>
                  </div>
               </div>

               <div className="border-4 border-dashed border-gray-100 rounded-2xl overflow-hidden p-4 bg-slate-50 flex flex-col items-center mb-8">
                  <img src={generatedImageUrl} alt="Preview Final" className="max-w-full h-auto shadow-2xl rounded-sm border border-gray-200" />
               </div>

               <div className="flex flex-col md:flex-row gap-4 mb-4">
                  <button 
                      onClick={shareToWhatsapp} 
                      className="flex-1 bg-[#25d366] hover:bg-[#128c7e] text-white font-black py-4 rounded-xl shadow-lg hover:shadow-xl shadow-green-500/20 flex items-center justify-center gap-3 transition-all transform hover:-translate-y-1"
                  >
                      <i className="fab fa-whatsapp text-2xl"></i>
                      ENVIAR NO WHATSAPP
                  </button>
                  <button 
                      onClick={downloadImage} 
                      className="flex-1 bg-[#2563eb] hover:bg-[#1d4ed8] text-white font-black py-4 rounded-xl shadow-lg hover:shadow-xl shadow-blue-500/20 flex items-center justify-center gap-3 transition-all transform hover:-translate-y-1"
                  >
                      <i className="fas fa-download text-xl"></i>
                      BAIXAR IMAGEM
                  </button>
               </div>

               <div className="bg-yellow-50 border border-yellow-100 rounded-xl p-4 text-center">
                  <p className="text-yellow-800 text-sm font-medium">
                     <i className="fas fa-info-circle mr-2"></i>
                     Caso precise fazer qualquer ajuste, basta mudar os dados na lista acima e clicar novamente em "Gerar Cartaz Final".
                  </p>
               </div>
           </div>
         )}

         <button 
           onClick={onBack}
           className="w-full bg-white hover:bg-gray-50 text-[#a62626] font-bold py-3 rounded-lg shadow-md hover:shadow-lg border border-red-200 flex items-center justify-center gap-2 transition-all mt-2"
         >
            <i className="fas fa-arrow-left"></i>
            Voltar ao Início
         </button>
      </div>

       <div className="w-full max-w-md mt-8 space-y-3">
        <div className="bg-[#fff1f2] rounded-xl py-3 px-4 text-center border border-[#fecdd3] shadow-sm">
          <span className="text-[#9f1239] text-xs font-medium">Sistema Desenvolvido pela ICM Planalto Linhares ES</span>
        </div>

        <a 
          href="https://www.instagram.com/icmplanalto.linhares?igsh=NHBjeWU5aXBiOTR1" 
          target="_blank" 
          rel="noopener noreferrer"
          className="w-full bg-[#fff1f2] rounded-xl py-3 px-4 flex items-center justify-center gap-2 border border-[#fecdd3] hover:bg-[#ffe4e6] transition-colors cursor-pointer shadow-sm hover:shadow-md"
        >
          <i className="fab fa-instagram text-pink-600 text-lg"></i>
          <span className="text-[#9f1239] text-sm font-medium">Instagram ICM Planalto</span>
        </a>
      </div>
    </div>
  );
};

export default HymnManager;

import React from 'react';
import { ChatMessage, MessageRole } from '../types';

interface ChatBubbleProps {
  message: ChatMessage;
}

// ChatBubble component for rendering individual messages in the chat interface
const ChatBubble: React.FC<ChatBubbleProps> = ({ message }) => {
  const isModel = message.role === MessageRole.MODEL;

  return (
    <div className={`flex w-full mb-6 ${isModel ? 'justify-start' : 'justify-end'}`}>
      <div className={`max-w-[85%] md:max-w-[70%] rounded-2xl p-4 shadow-sm ${
        isModel 
          ? 'bg-slate-800 rounded-tl-none text-slate-200' 
          : 'bg-indigo-600 rounded-tr-none text-white'
      } ${message.isError ? 'border border-red-500/50 bg-red-500/10' : ''}`}>

        {/* Render uploaded image if present */}
        {message.image && (
          <div className="mb-3 rounded-lg overflow-hidden border border-white/10">
            <img src={`data:image/jpeg;base64,${message.image}`} alt="User upload" className="max-w-full h-auto" />
          </div>
        )}

        {/* Render message text content */}
        <div className="text-sm md:text-base whitespace-pre-wrap break-words leading-relaxed">
          {message.text}
        </div>

        {/* Render search grounding sources if available */}
        {message.groundingSources && message.groundingSources.length > 0 && (
          <div className="mt-4 pt-3 border-t border-white/10">
            <p className="text-xs font-bold mb-2 text-slate-400 uppercase tracking-wider">Fontes:</p>
