import { GoogleGenAI, LiveServerMessage, Modality } from "@google/genai";
import { decode, decodeAudioData, createPcmBlob } from "../utils/audioUtils";
import { GroundingSource } from "../types";

// --- Configuration ---
// Models updated to comply with current best practices
const TEXT_MODEL = 'gemini-3-flash-preview';
const LIVE_MODEL = 'gemini-2.5-flash-native-audio-preview-09-2025';

// Initialize Client with direct process.env.API_KEY access
// Always use a named parameter: { apiKey: process.env.API_KEY }
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// --- Text & Image Service ---

interface GenerateResponse {
  text: string;
  groundingSources?: GroundingSource[];
}

export const sendMessageToGemini = async (
  prompt: string, 
  imageBase64?: string,
  useSearch: boolean = false
): Promise<GenerateResponse> => {
  const parts: any[] = [];

  if (imageBase64) {
    parts.push({
      inlineData: {
        data: imageBase64,
        mimeType: 'image/jpeg', 
      },
    });
  }

  parts.push({ text: prompt });

  const config: any = {
    systemInstruction: "Você é um assistente útil, amigável e conciso da Igreja Cristã Maranata. Você responde sempre em Português do Brasil."
  };

  if (useSearch) {
    config.tools = [{ googleSearch: {} }];
  }

  try {
    const response = await ai.models.generateContent({
      model: TEXT_MODEL,
      contents: { parts },
      config: config
    });

    // Extract text output using property access (.text)
    const text = response.text || "Nenhuma resposta gerada.";

    // Extract Grounding Metadata for search grounding
    const groundingSources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web) {
          groundingSources.push({
            title: chunk.web.title || "Fonte Web",
            uri: chunk.web.uri
          });
        }
      });
    }

    return { text, groundingSources };

  } catch (error: any) {
    console.error("Gemini API Error:", error);
    throw new Error(error.message || "Falha na comunicação com o Gemini.");
  }
};


// --- Live API Service ---

export class LiveSessionManager {
  private sessionPromise: Promise<any> | null = null;
  private inputAudioContext: AudioContext | null = null;
  private outputAudioContext: AudioContext | null = null;
  private nextStartTime: number = 0;
  private sources: Set<AudioBufferSourceNode> = new Set();
  private stream: MediaStream | null = null;
  private scriptProcessor: ScriptProcessorNode | null = null;

  constructor(
    private onVolumeUpdate: (vol: number) => void,
    private onClose: () => void
  ) {}

  async connect() {
    this.inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
    this.outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    this.nextStartTime = 0;

    // Get Microphone Stream
    this.stream = await navigator.mediaDevices.getUserMedia({ audio: true });

    // Connect to Gemini Live API
    this.sessionPromise = ai.live.connect({
      model: LIVE_MODEL,
      callbacks: {
        onopen: this.handleOpen.bind(this),
        onmessage: this.handleMessage.bind(this),
        onerror: (e) => console.error("Live API Error:", e),
        onclose: (e) => {
            console.log("Live API Closed", e);
            this.disconnect();
            this.onClose();
        },
      },
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
        },
        systemInstruction: "Você é um assistente virtual prestativo da Igreja Cristã Maranata. Fale de forma clara, natural e concisa em Português do Brasil.",
      },
    });
  }

  private handleOpen() {
    if (!this.inputAudioContext || !this.stream) return;

    const source = this.inputAudioContext.createMediaStreamSource(this.stream);
    this.scriptProcessor = this.inputAudioContext.createScriptProcessor(4096, 1, 1);

    this.scriptProcessor.onaudioprocess = (e) => {
      const inputData = e.inputBuffer.getChannelData(0);

      // Volume calculation for UI visualization
      let sum = 0;
      for(let i=0; i<inputData.length; i++) sum += inputData[i] * inputData[i];
      const rms = Math.sqrt(sum / inputData.length);
      this.onVolumeUpdate(rms);

      const pcmBlob = createPcmBlob(inputData);

      // CRITICAL: initiate sendRealtimeInput after live.connect call resolves.
      this.sessionPromise?.then((session) => {
        session.sendRealtimeInput({ media: pcmBlob });
      });
    };

    source.connect(this.scriptProcessor);
    this.scriptProcessor.connect(this.inputAudioContext.destination);
  }

  private async handleMessage(message: LiveServerMessage) {
    // Process model audio output bytes from LiveServerMessage
    const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;

    if (base64Audio && this.outputAudioContext) {
      // Audio bytes from API are raw PCM data
      const audioBuffer = await decodeAudioData(
        decode(base64Audio),
        this.outputAudioContext,
        24000,
        1
      );

      // Playback management using nextStartTime for gapless audio
      this.nextStartTime = Math.max(this.nextStartTime, this.outputAudioContext.currentTime);
      const source = this.outputAudioContext.createBufferSource();
      source.buffer = audioBuffer;
      const gainNode = this.outputAudioContext.createGain();
      gainNode.gain.value = 1.0; 

      source.connect(gainNode);
      gainNode.connect(this.outputAudioContext.destination);

      source.addEventListener('ended', () => {
        this.sources.delete(source);
      });

      source.start(this.nextStartTime);
      this.nextStartTime += audioBuffer.duration;
      this.sources.add(source);
    }

    // Handle model interruptions
    if (message.serverContent?.interrupted) {
      this.sources.forEach(src => src.stop());
      this.sources.clear();
      this.nextStartTime = 0;
    }
  }

  disconnect() {
    this.sessionPromise?.then(session => session.close());

    // Clean up hardware resources
    this.stream?.getTracks().forEach(track => track.stop());
    this.scriptProcessor?.disconnect();

    this.inputAudioContext?.close();
    this.outputAudioContext?.close();

    this.inputAudioContext = null;
    this.outputAudioContext = null;
    this.stream = null;
    this.sessionPromise = null;
  }
}

