// Gerador de ID simples para evitar dependências externas pesadas no navegador
const generateId = () => Math.random().toString(36).substring(2, 11);

const App: React.FC = () => {
  // Estado de Navegação
  const [mode, setMode] = useState<AppMode>(AppMode.HOME);

  // Estado do Chat
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: generateId(),
      role: MessageRole.MODEL,
      text: "Olá! Eu sou o Assistente Virtual do Sistema Culto Profético. Como posso ajudar hoje?"
    }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<File | null>(null);
  const [useSearch, setUseSearch] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Auto-scroll para o final do chat
  useEffect(() => {
    if (mode === AppMode.CHAT) {
      messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }
  }, [messages, mode]);

  // Handlers do Chat
  const handleSend = async () => {
    if ((!input.trim() && !selectedImage) || isLoading) return;

    let imageBase64: string | undefined;
    if (selectedImage) {
      try {
        imageBase64 = await fileToBase64(selectedImage);
      } catch (e) {
        console.error("Erro ao processar imagem", e);
        return;
      }
    }

    const newUserMsg: ChatMessage = {
      id: generateId(),
      role: MessageRole.USER,
      text: input,
      image: imageBase64
    };

    setMessages(prev => [...prev, newUserMsg]);
    setInput('');
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const response = await sendMessageToGemini(
        newUserMsg.text || (newUserMsg.image ? "Analise esta imagem" : ""), 
        newUserMsg.image,
        useSearch
      );

      const modelMsg: ChatMessage = {
        id: generateId(),
        role: MessageRole.MODEL,
        text: response.text,
        groundingSources: response.groundingSources
      };

      setMessages(prev => [...prev, modelMsg]);
    } catch (error) {
      setMessages(prev => [...prev, {
        id: generateId(),
        role: MessageRole.MODEL,
        text: "Desculpe, encontrei um erro ao processar sua solicitação.",
        isError: true
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setSelectedImage(e.target.files[0]);
    }
  };

