          onBack={() => setMode(AppMode.HOME)} 
          onNavigateToServiceData={() => setMode(AppMode.SERVICE_DATA)}
        />;

      case AppMode.SERVICE_DATA:
        return <ServiceDataForm onBack={() => setMode(AppMode.OTHER_APPS_MENU)} />;

      case AppMode.LIVE:
        return <LiveInterface onBack={() => setMode(AppMode.CHAT)} />;

      case AppMode.CHAT:
        return (
          <div className="flex h-screen bg-slate-950 text-slate-200 overflow-hidden font-sans">
            <aside className="hidden md:flex flex-col w-64 bg-slate-900 border-r border-slate-800 p-4">
              <div className="flex items-center gap-3 mb-8 px-2 cursor-pointer" onClick={() => setMode(AppMode.HOME)}>
                <div className="w-8 h-8 rounded-lg bg-gradient-to-tr from-indigo-500 to-purple-500 flex items-center justify-center">
                  <i className="fas fa-home text-white text-sm"></i>
                </div>
                <h1 className="font-bold text-lg tracking-tight">Menu Principal</h1>
              </div>
              <nav className="flex-1 space-y-2">
                <button className="w-full flex items-center gap-3 px-4 py-3 rounded-xl bg-indigo-600 text-white shadow-lg shadow-indigo-500/20">
                  <i className="fas fa-message w-5"></i>
                  <span>Chat</span>
                </button>
                <button onClick={() => setMode(AppMode.LIVE)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-800 text-slate-400 transition-all group">
                  <i className="fas fa-microphone-lines w-5 group-hover:text-indigo-400"></i>
                  <span>Voz ao Vivo</span>
                </button>
              </nav>
            </aside>
            <main className="flex-1 flex flex-col min-w-0 relative">
              <header className="md:hidden h-14 border-b border-slate-800 flex items-center justify-between px-4 bg-slate-900/50 backdrop-blur-md sticky top-0 z-20">
                 <button onClick={() => setMode(AppMode.HOME)} className="flex items-center gap-2">
                    <i className="fas fa-arrow-left text-slate-400"></i>
