 */
export const sendMessageToGemini = async (
  prompt: string, 
  imageBase64?: string
): Promise<{ text: string; sources?: GroundingSource[] }> => {
  // Use process.env.API_KEY directly as per SDK requirements
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("Chave API não configurada.");

  const ai = new GoogleGenAI({ apiKey });

  const parts: any[] = [];
  if (imageBase64) {
    parts.push({
      inlineData: {
        data: imageBase64,
        mimeType: 'image/jpeg', 
      },
    });
  }
  parts.push({ text: prompt });

  try {
    // Calling generateContent directly with model name as per guidelines
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts }],
      config: {
        systemInstruction: "Você é um assistente virtual da Igreja Cristã Maranata. Seja prestativo, use vocabulário cristão adequado e responda em Português do Brasil.",
        tools: [{ googleSearch: {} }]
      }
    });

    // Extract search grounding sources for display
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    const sources: GroundingSource[] = [];
    if (groundingChunks) {
      groundingChunks.forEach((chunk: any) => {
