import { GoogleGenAI, Modality, GenerateContentResponse, LiveServerMessage, Blob } from "@google/genai";
import { GroundingSource } from "../types";

// Função para obter o cliente sempre com a chave atualizada
const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API Key não encontrada.");
  return new GoogleGenAI({ apiKey });
};

/**
 * Chat Text/Image Service
 */
export const sendMessageToGemini = async (
  prompt: string, 
  imageBase64?: string
): Promise<{ text: string; sources?: GroundingSource[] }> => {
  const ai = getClient();

  const parts: any[] = [];
  if (imageBase64) {
    parts.push({
      inlineData: {
        data: imageBase64,
        mimeType: 'image/jpeg', 
      },
    });
  }
  parts.push({ text: prompt });

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts }],
      config: {
        systemInstruction: "Você é o Assistente Virtual da Igreja Cristã Maranata (ICM). Use vocabulário cristão, seja amável, respeitoso e conciso. Responda em Português do Brasil.",
        tools: [{ googleSearch: {} }]
      }
    });

    const sources: GroundingSource[] = [];
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (groundingChunks) {
      groundingChunks.forEach((chunk: any) => {
        if (chunk.web) {
          sources.push({
            title: chunk.web.title || "Fonte Web",
            uri: chunk.web.uri
          });
        }
      });
    }

    return { 
      text: response.text || "Não consegui processar uma resposta.",
      sources: sources.length > 0 ? sources : undefined
    };
  } catch (error: any) {
    console.error("Gemini Chat Error:", error);
    throw new Error(error.message || "Falha na conexão com a inteligência artificial.");
  }
};

/**
 * Live Audio Session Manager
 */
export class LiveSessionManager {
  private sessionPromise: Promise<any> | null = null;
  private onVolume: (v: number) => void;
  private onClose: () => void;
  private stream: MediaStream | null = null;
  private audioCtx: AudioContext | null = null;
  private outputCtx: AudioContext | null = null;
  private nextStartTime = 0;
  private sources = new Set<AudioBufferSourceNode>();

  constructor(onVolume: (v: number) => void, onClose: () => void) {
    this.onVolume = onVolume;
    this.onClose = onClose;
  }

  async connect() {
    const ai = getClient();
    this.audioCtx = new AudioContext({ sampleRate: 16000 });
    this.outputCtx = new AudioContext({ sampleRate: 24000 });
    this.stream = await navigator.mediaDevices.getUserMedia({ audio: true });

    this.sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-09-2025',
      callbacks: {
        onopen: () => {
          const source = this.audioCtx!.createMediaStreamSource(this.stream!);
          const processor = this.audioCtx!.createScriptProcessor(4096, 1, 1);
          processor.onaudioprocess = (e) => {
            const inputData = e.inputBuffer.getChannelData(0);
            let sum = 0;
            for(let i=0; i<inputData.length; i++) sum += inputData[i] * inputData[i];
            this.onVolume(Math.sqrt(sum / inputData.length));

            const pcmBlob = this.createBlob(inputData);
            this.sessionPromise!.then(s => s.sendRealtimeInput({ media: pcmBlob }));
          };
          source.connect(processor);
          processor.connect(this.audioCtx!.destination);
        },
        onmessage: async (msg: LiveServerMessage) => {
          const base64 = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64 && this.outputCtx) {
            const buffer = await this.decodeAudio(base64);
            this.nextStartTime = Math.max(this.nextStartTime, this.outputCtx.currentTime);
            const source = this.outputCtx.createBufferSource();
            source.buffer = buffer;
            source.connect(this.outputCtx.destination);
            source.start(this.nextStartTime);
            this.nextStartTime += buffer.duration;
            this.sources.add(source);
          }
          if (msg.serverContent?.interrupted) {
            this.sources.forEach(s => s.stop());
            this.sources.clear();
            this.nextStartTime = 0;
          }
        },
        onclose: () => this.onClose(),
        onerror: (e) => console.error("Live Error:", e)
      },
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Puck' } } },
        systemInstruction: "Você é um assistente da ICM conversando por voz. Responda de forma curta e espiritual."
      }
    });
  }

  disconnect() {
    this.sessionPromise?.then(s => s.close());
    this.stream?.getTracks().forEach(t => t.stop());
    this.audioCtx?.close();
    this.outputCtx?.close();
  }

  private createBlob(data: Float32Array): Blob {
    const int16 = new Int16Array(data.length);
    for(let i=0; i<data.length; i++) int16[i] = data[i] * 32768;
    let binary = '';
    const bytes = new Uint8Array(int16.buffer);
    for(let i=0; i<bytes.byteLength; i++) binary += String.fromCharCode(bytes[i]);
    return { data: btoa(binary), mimeType: 'audio/pcm;rate=16000' };
  }

  private async decodeAudio(base64: string): Promise<AudioBuffer> {
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for(let i=0; i<binary.length; i++) bytes[i] = binary.charCodeAt(i);
    const dataInt16 = new Int16Array(bytes.buffer);
    const buffer = this.outputCtx!.createBuffer(1, dataInt16.length, 24000);
    const channelData = buffer.getChannelData(0);
    for(let i=0; i<dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
    return buffer;
  }
}

import React, { useState, useEffect, useRef } from 'react';
import { AppMode, ChatMessage, MessageRole } from './types';
import HomeScreen from './components/HomeScreen';
import HymnManager from './components/HymnManager';
import GiftRegistration from './components/GiftRegistration';
import OtherAppsMenu from './components/OtherAppsMenu';
import ServiceDataForm from './components/ServiceDataForm';
import LiveInterface from './components/LiveInterface';
import ChatBubble from './components/ChatBubble';
import { sendMessageToGemini } from './services/geminiService';
import { fileToBase64 } from './utils/audioUtils';

const App: React.FC = () => {
  const [mode, setMode] = useState<AppMode>(AppMode.HOME);

  // Chat State
  const [messages, setMessages] = useState<ChatMessage[]>([
    { id: '1', role: MessageRole.MODEL, text: 'Olá! Sou seu assistente da ICM. Como posso ajudar você hoje?' }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = async () => {
    if ((!input.trim() && !selectedFile) || loading) return;

    let imageBase64: string | undefined;
    if (selectedFile) {
      imageBase64 = await fileToBase64(selectedFile);
    }

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: MessageRole.USER,
      text: input,
      image: imageBase64
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setSelectedFile(null);
    setLoading(true);

    try {
      const response = await sendMessageToGemini(userMsg.text || "O que tem nesta imagem?", imageBase64);
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: MessageRole.MODEL,
        text: response.text,
        groundingSources: response.sources
      }]);
    } catch (err: any) {
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: MessageRole.MODEL,
        text: 'Desculpe, tive um problema ao processar sua mensagem.',
        isError: true
      }]);
    } finally {
      setLoading(false);
    }
  };

  const renderContent = () => {
    switch (mode) {
      case AppMode.HYMN_LIST:
        return <HymnManager onBack={() => setMode(AppMode.HOME)} />;
      case AppMode.GIFT_REGISTRATION:
        return <GiftRegistration onBack={() => setMode(AppMode.HOME)} />;
      case AppMode.OTHER_APPS_MENU:
        return <OtherAppsMenu onBack={() => setMode(AppMode.HOME)} onNavigateToServiceData={() => setMode(AppMode.SERVICE_DATA)} />;
      case AppMode.SERVICE_DATA:
        return <ServiceDataForm onBack={() => setMode(AppMode.OTHER_APPS_MENU)} />;
      case AppMode.LIVE:
        return <LiveInterface onBack={() => setMode(AppMode.CHAT)} />;
      case AppMode.CHAT:
        return (
          <div className="flex flex-col h-screen bg-slate-950 animate-fade-in">
            <header className="flex items-center justify-between p-4 border-b border-slate-800 bg-slate-900/50 backdrop-blur-md">
              <button onClick={() => setMode(AppMode.HOME)} className="text-slate-400 hover:text-white p-2">
                <i className="fas fa-chevron-left text-xl"></i>
              </button>
              <h2 className="text-lg font-bold text-white">Assistente ICM</h2>
              <button onClick={() => setMode(AppMode.LIVE)} className="bg-indigo-600 text-white w-10 h-10 rounded-full flex items-center justify-center shadow-lg shadow-indigo-500/20">
                <i className="fas fa-microphone"></i>
              </button>
            </header>

            <div className="flex-1 overflow-y-auto p-4 space-y-2">
              <div className="max-w-3xl mx-auto">
                {messages.map(m => <ChatBubble key={m.id} message={m} />)}
                {loading && (
                  <div className="flex justify-start mb-4">
                    <div className="bg-slate-800 p-4 rounded-2xl rounded-tl-none flex gap-1">
                      <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce"></div>
                      <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                      <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                    </div>
                  </div>
                )}
                <div ref={scrollRef} />
              </div>
            </div>

            <footer className="p-4 bg-slate-900/80 border-t border-slate-800">
              <div className="max-w-3xl mx-auto space-y-2">
                {selectedFile && (
                  <div className="flex items-center gap-2 bg-slate-800 p-2 rounded-lg w-fit text-xs text-slate-300">
                    <i className="fas fa-image text-indigo-400"></i>
                    <span className="truncate max-w-[150px]">{selectedFile.name}</span>
                    <button onClick={() => setSelectedFile(null)} className="text-red-400"><i className="fas fa-times"></i></button>
                  </div>
                )}
                <div className="flex items-end gap-2">
                  <button onClick={() => fileInputRef.current?.click()} className="p-3 bg-slate-800 text-slate-400 rounded-xl hover:text-indigo-400 transition-colors">
                    <i className="fas fa-paperclip text-xl"></i>
                  </button>
                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => e.target.files && setSelectedFile(e.target.files[0])} />
                  <textarea 
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                    placeholder="Pergunte sobre a Bíblia ou orientações..."
                    className="flex-1 bg-slate-800 border-none rounded-xl p-3 text-white placeholder-slate-500 resize-none focus:ring-2 focus:ring-indigo-500 max-h-32"
                    rows={1}
                  />
                  <button onClick={handleSendMessage} disabled={loading} className="p-3 bg-indigo-600 text-white rounded-xl hover:bg-indigo-500 disabled:opacity-50 transition-all">
                    <i className="fas fa-paper-plane text-xl"></i>
                  </button>
                </div>
              </div>
            </footer>
          </div>
        );
      default:
        return (
          <HomeScreen 
            onNavigateToChat={() => setMode(AppMode.CHAT)} 
            onNavigateToHymns={() => setMode(AppMode.HYMN_LIST)}
            onNavigateToGifts={() => setMode(AppMode.GIFT_REGISTRATION)}
            onNavigateToOtherSystems={() => setMode(AppMode.OTHER_APPS_MENU)}
          />
        );
    }
  };

  return <div className="min-h-screen text-slate-200">{renderContent()}</div>;
};

export default App;

