      role: MessageRole.USER,
      text: input,
      image: imageBase64
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setSelectedFile(null);
    setLoading(true);

    try {
      const response = await sendMessageToGemini(userMsg.text || "Analise esta imagem sob a perspectiva da igreja.", imageBase64);
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: MessageRole.MODEL,
        text: response.text,
        groundingSources: response.sources
      }]);
    } catch (err: any) {
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: MessageRole.MODEL,
        text: 'Desculpe, tive um problema técnico ao processar sua mensagem.',
        isError: true
      }]);
    } finally {
      setLoading(false);
    }
  };

  const renderContent = () => {
    switch (mode) {
      case AppMode.HYMN_LIST:
        return <HymnManager onBack={() => setMode(AppMode.HOME)} />;
      case AppMode.GIFT_REGISTRATION:
        return <GiftRegistration onBack={() => setMode(AppMode.HOME)} />;
      case AppMode.OTHER_APPS_MENU:
        return <OtherAppsMenu onBack={() => setMode(AppMode.HOME)} onNavigateToServiceData={() => setMode(AppMode.SERVICE_DATA)} />;
      case AppMode.SERVICE_DATA:
        return <ServiceDataForm onBack={() => setMode(AppMode.OTHER_APPS_MENU)} />;
      case AppMode.LIVE:
        return <LiveInterface onBack={() => setMode(AppMode.CHAT)} />;
      case AppMode.CHAT:
        return (
          <div className="flex flex-col h-screen bg-slate-50 animate-fade-in">
            <header className="flex items-center justify-between p-4 border-b border-slate-200 bg-white shadow-sm z-10">
              <button onClick={() => setMode(AppMode.HOME)} className="text-slate-500 hover:text-slate-800 p-2">
                <i className="fas fa-chevron-left text-xl"></i>
              </button>
              <div className="text-center">
                <h2 className="text-lg font-bold text-slate-800">Assistente ICM</h2>
                <span className="text-[10px] text-emerald-500 font-bold uppercase tracking-widest">Inteligência Artificial</span>
              </div>
              <button onClick={() => setMode(AppMode.LIVE)} className="bg-rose-600 text-white w-10 h-10 rounded-full flex items-center justify-center shadow-lg hover:scale-110 transition-transform">
                <i className="fas fa-microphone"></i>
              </button>
            </header>

            <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50/50">
              <div className="max-w-3xl mx-auto">
                {messages.map(m => <ChatBubble key={m.id} message={m} />)}
                {loading && (
                  <div className="flex justify-start mb-4">
                    <div className="bg-white border border-slate-200 p-4 rounded-2xl rounded-tl-none flex gap-1 shadow-sm">
                      <div className="w-2 h-2 bg-rose-400 rounded-full animate-bounce"></div>
                      <div className="w-2 h-2 bg-rose-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                      <div className="w-2 h-2 bg-rose-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                    </div>
                  </div>
                )}
                <div ref={scrollRef} />
              </div>
            </div>

            <footer className="p-4 bg-white border-t border-slate-200">
              <div className="max-w-3xl mx-auto">
                {selectedFile && (
                  <div className="flex items-center gap-2 bg-rose-50 p-2 rounded-lg w-fit text-xs text-rose-700 mb-2 border border-rose-100">
                    <i className="fas fa-image"></i>
                    <span className="truncate max-w-[150px]">{selectedFile.name}</span>
                    <button onClick={() => setSelectedFile(null)} className="text-rose-400 hover:text-rose-600"><i className="fas fa-times"></i></button>
                  </div>
                )}
                <div className="flex items-end gap-2">
                  <button onClick={() => fileInputRef.current?.click()} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:text-rose-600 transition-colors">
                    <i className="fas fa-camera text-xl"></i>
                  </button>
                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => e.target.files && setSelectedFile(e.target.files[0])} />
                  <textarea 
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                    placeholder="Pergunte sobre hinos, Bíblia ou orientações..."
                    className="flex-1 bg-slate-100 border border-slate-200 rounded-xl p-3 text-slate-800 placeholder-slate-400 resize-none focus:ring-2 focus:ring-rose-500 focus:bg-white outline-none max-h-32"
                    rows={1}
                  />
                  <button onClick={handleSendMessage} disabled={loading} className="p-3 bg-rose-600 text-white rounded-xl hover:bg-rose-700 disabled:opacity-50 shadow-md transition-all">
                    <i className="fas fa-paper-plane text-xl"></i>
                  </button>
                </div>
              </div>
            </footer>
          </div>
        );
      default:
        return (
          <HomeScreen 
            onNavigateToChat={() => setMode(AppMode.CHAT)} 
            onNavigateToHymns={() => setMode(AppMode.HYMN_LIST)}
            onNavigateToGifts={() => setMode(AppMode.GIFT_REGISTRATION)}
            onNavigateToOtherSystems={() => setMode(AppMode.OTHER_APPS_MENU)}
          />
        );
    }
  };

  return <div className="min-h-screen text-slate-800">{renderContent()}</div>;
};

export default App;

