import React, { useState, useEffect, useRef } from 'react';
import { COLETANEA_DATA, CIAS_DATA } from '../utils/hymnData';

interface HymnRow {
  number: string;
  name: string;
}

interface HymnManagerProps {
  onBack: () => void;
}

const HymnManager: React.FC<HymnManagerProps> = ({ onBack }) => {
  // State
  const [activeRow, setActiveRow] = useState<number>(0);
  const [rows, setRows] = useState<HymnRow[]>(Array(8).fill({ number: '', name: '' }));
  const [searchQuery, setSearchQuery] = useState('');
  const [hymnType, setHymnType] = useState<'coletanea' | 'cias'>('coletanea');
  const [searchResults, setSearchResults] = useState<{number: string, name: string}[]>([]);
  const [isAfterWordMode, setIsAfterWordMode] = useState(false);
  const [generatedImageUrl, setGeneratedImageUrl] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);

  // Voice Recognition
  const [isListening, setIsListening] = useState(false);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.continuous = true;
      recognition.interimResults = true;
      recognition.lang = 'pt-BR';
      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);
      recognition.onresult = (event: any) => {
        let finalTranscript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) finalTranscript += event.results[i][0].transcript;
        }
        if (finalTranscript) {
          const cleanText = finalTranscript.replace(/[.]/g, '').toUpperCase();
          setSearchQuery(prev => (prev && !prev.endsWith(' ') ? prev + ' ' + cleanText : prev + cleanText));
        }
      };
      recognitionRef.current = recognition;
    }
  }, []);

  const toggleListening = () => {
    if (!recognitionRef.current) return alert("Seu navegador não suporta reconhecimento de voz.");
    isListening ? recognitionRef.current.stop() : (setSearchQuery(''), recognitionRef.current.start());
  };

  // Busca
  useEffect(() => {
    if (!searchQuery.trim()) return setSearchResults([]);
    const q = searchQuery.toLowerCase();
    const sourceDB = hymnType === 'coletanea' ? COLETANEA_DATA : CIAS_DATA;
    setSearchResults(sourceDB.filter(h => h.number.includes(q) || h.name.toLowerCase().includes(q)).slice(0, 50));
  }, [searchQuery, hymnType]);

  const selectHymn = (hymn: { number: string, name: string }) => {
    const newRows = [...rows];
    newRows[activeRow] = { number: hymn.number, name: hymn.name.toUpperCase() };
    if (activeRow === newRows.length - 1) newRows.push({ number: '', name: '' });
    setRows(newRows);
    setActiveRow(activeRow + 1);
    setSearchQuery('');
    setGeneratedImageUrl(null);
  };

  const updateRow = (index: number, field: keyof HymnRow, value: string) => {
    const newRows = [...rows];
    newRows[index] = { ...newRows[index], [field]: value.toUpperCase() };
    setRows(newRows);
    setGeneratedImageUrl(null);
  };

  const handleMoveRow = (index: number, direction: 'up' | 'down') => {
    const newRows = [...rows];
    if (direction === 'up' && index > 0) {
      [newRows[index], newRows[index - 1]] = [newRows[index - 1], newRows[index]];
    } else if (direction === 'down' && index < rows.length - 1) {
      [newRows[index], newRows[index + 1]] = [newRows[index + 1], newRows[index]];
    }
    setRows(newRows);
    setGeneratedImageUrl(null);
  };

  const clearList = () => {
    if (window.confirm("Limpar lista?")) {
      setRows(Array(isAfterWordMode ? 3 : 8).fill({ number: '', name: '' }));
      setActiveRow(0);
      setGeneratedImageUrl(null);
    }
  };

  const generateImage = async () => {
    setIsGenerating(true);
    await new Promise(r => setTimeout(r, 400));

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return setIsGenerating(false);

    // Configurações de Dimensão baseadas no layout enviado (Proporção aproximada)
    const tableWidth = 1000;
    const headerHeight = 80;
    const tableHeaderHeight = 80;
    const rowHeight = 70;
    const padding = 40;

    canvas.width = tableWidth + (padding * 2);
    canvas.height = headerHeight + tableHeaderHeight + (rows.length * rowHeight) + (padding * 2);

    // Fundo branco puro
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Ajuste de coordenadas para começar após o padding
    ctx.save();
    ctx.translate(padding, padding);

    // 1. Linha Superior: Título e Data
    ctx.strokeStyle = '#000000';
    ctx.lineWidth = 3;
    ctx.strokeRect(0, 0, tableWidth, headerHeight);

    ctx.fillStyle = '#000000';
    ctx.font = 'bold 36px Arial';
    ctx.textBaseline = 'middle';
    ctx.textAlign = 'left';
    ctx.fillText('LOUVORES', 20, headerHeight / 2);

    const today = new Date();
    const days = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];
    const dateStr = `${days[today.getDay()]} - ${today.toLocaleDateString('pt-BR')}`;
    ctx.textAlign = 'right';
    ctx.fillText(dateStr, tableWidth - 20, headerHeight / 2);

    // 2. Cabeçalho da Tabela (Cinza)
    const startY = headerHeight;
    ctx.fillStyle = '#999999';
    ctx.fillRect(0, startY, tableWidth, tableHeaderHeight);
    ctx.strokeRect(0, startY, tableWidth, tableHeaderHeight);

    // Divisor vertical do cabeçalho
    const colDividerX = 200;
    ctx.beginPath();
    ctx.moveTo(colDividerX, startY);
    ctx.lineTo(colDividerX, startY + tableHeaderHeight);
    ctx.stroke();

    ctx.fillStyle = '#000000';
    ctx.font = 'bold 32px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('Nº', colDividerX / 2, startY + (tableHeaderHeight / 2));
    ctx.fillText('Nome do Hino', colDividerX + (tableWidth - colDividerX) / 2, startY + (tableHeaderHeight / 2));

    // 3. Linhas da Tabela
    rows.forEach((row, i) => {
      const y = startY + tableHeaderHeight + (i * rowHeight);

      // Borda da linha
      ctx.strokeRect(0, y, tableWidth, rowHeight);

      // Divisor vertical
      ctx.beginPath();
      ctx.moveTo(colDividerX, y);
      ctx.lineTo(colDividerX, y + rowHeight);
      ctx.stroke();

      // Conteúdo
      ctx.fillStyle = '#000000';
      ctx.font = '30px Arial';
      ctx.textAlign = 'center';
      if (row.number) {
        ctx.fillText(row.number, colDividerX / 2, y + (rowHeight / 2));
      }

      ctx.textAlign = 'left';
      if (row.name) {
        ctx.fillText(row.name, colDividerX + 30, y + (rowHeight / 2));
      }
    });

    ctx.restore();

    setGeneratedImageUrl(canvas.toDataURL('image/png'));
    setIsGenerating(false);
    setTimeout(() => document.getElementById('preview-section')?.scrollIntoView({ behavior: 'smooth' }), 100);
  };

  return (
    <div className="min-h-screen bg-[#ffeeefff] flex flex-col items-center pt-8 pb-8 px-4 font-sans">
      <h1 className="text-3xl font-bold text-[#a62626] mb-6 uppercase text-center">{isAfterWordMode ? "Louvor Após a Palavra" : "Lista de Louvores"}</h1>

      <button onClick={() => { setIsAfterWordMode(!isAfterWordMode); setRows(Array(!isAfterWordMode ? 3 : 8).fill({number:'', name:''})); }} className="bg-[#dc2626] text-white font-bold py-2 px-6 rounded-md shadow-md mb-8 uppercase text-sm">
        {isAfterWordMode ? "Voltar para Lista Completa" : "Ir para Louvor Após a Palavra"}
      </button>

      <div className="bg-white rounded-3xl shadow-xl w-full max-w-4xl p-6 md:p-8">
        <div className="border border-red-100 rounded-xl p-4 mb-6 bg-red-50/30">
          <div className="flex gap-4 mb-4 text-sm font-bold text-[#a62626]">
             <label className="flex items-center gap-2 cursor-pointer"><input type="radio" checked={hymnType === 'coletanea'} onChange={() => setHymnType('coletanea')} /> Coletânea</label>
             <label className="flex items-center gap-2 cursor-pointer"><input type="radio" checked={hymnType === 'cias'} onChange={() => setHymnType('cias')} /> Cias</label>
          </div>
          <div className="relative">
            <input type="text" placeholder="BUSCAR LOUVOR..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value.toUpperCase())} className="w-full pl-4 pr-12 py-3 border border-red-200 rounded-md outline-none text-black uppercase" />
            <button onClick={toggleListening} className={`absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 rounded-full flex items-center justify-center ${isListening ? 'bg-red-600 text-white animate-pulse' : 'text-gray-400'}`}><i className="fas fa-microphone"></i></button>
            {searchResults.length > 0 && (
              <div className="absolute top-full left-0 right-0 bg-white border rounded-md shadow-lg z-10 max-h-48 overflow-y-auto">
                {searchResults.map((h, i) => (
                   <button key={i} onClick={() => selectHymn(h)} className="w-full text-left px-4 py-2 text-sm hover:bg-red-50 flex justify-between border-b uppercase">
                     <span>{h.name}</span><span className="font-bold text-red-500">{h.number}</span>
                   </button>
                ))}
              </div>
            )}
          </div>
        </div>

        <button onClick={clearList} className="mb-4 bg-red-100 text-red-700 px-4 py-2 rounded-md text-xs font-bold uppercase"><i className="fas fa-trash mr-2"></i>Limpar Tudo</button>

        <div className="border border-slate-300 rounded overflow-hidden">
           {rows.map((row, idx) => (
             <div key={idx} className={`flex border-b last:border-0 items-center ${activeRow === idx ? 'bg-blue-50' : 'bg-white'}`}>
                <div className="w-10 border-r flex flex-col items-center bg-slate-50 text-[10px] text-slate-400">
                  <button onClick={() => handleMoveRow(idx, 'up')}><i className="fas fa-chevron-up"></i></button>
                  <button onClick={() => handleMoveRow(idx, 'down')}><i className="fas fa-chevron-down"></i></button>
                </div>
                <input type="text" value={row.number} onChange={(e) => updateRow(idx, 'number', e.target.value)} className="w-16 border-r text-center font-bold p-2 outline-none bg-transparent" placeholder="Nº" />
                <input type="text" value={row.name} onChange={(e) => updateRow(idx, 'name', e.target.value)} className="flex-1 p-2 outline-none uppercase bg-transparent" placeholder="NOME DO HINO" />
             </div>
           ))}
        </div>
      </div>

      <div className="w-full max-w-4xl mt-6 flex flex-col gap-6">
         <button onClick={generateImage} disabled={isGenerating} className="w-full bg-[#dc2626] text-white font-bold py-4 rounded-lg shadow-lg flex items-center justify-center gap-2">
            {isGenerating ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-image"></i>}
            GERAR IMAGEM
         </button>

         {generatedImageUrl && (
           <div id="preview-section" className="bg-white rounded-3xl shadow-2xl p-6 border-2 border-red-50">
               <h3 className="text-[#a62626] font-bold text-xl mb-4 text-center">Conferência Final</h3>
               <div className="bg-slate-50 p-4 rounded-xl flex justify-center mb-6">
                  <img src={generatedImageUrl} alt="Preview" className="max-w-full h-auto shadow-lg border" />
               </div>
               <div className="flex flex-col md:flex-row gap-4">
                  <button onClick={async () => { const res = await fetch(generatedImageUrl); const blob = await res.blob(); const file = new File([blob], "louvores.png", { type: "image/png" }); if (navigator.canShare) await navigator.share({ files: [file] }); }} className="flex-1 bg-[#25d366] text-white font-black py-4 rounded-xl shadow-lg flex items-center justify-center gap-3">
                      <i className="fab fa-whatsapp text-2xl"></i> WHATSAPP
                  </button>
                  <button onClick={() => { const link = document.createElement('a'); link.download = 'louvores.png'; link.href = generatedImageUrl; link.click(); }} className="flex-1 bg-blue-600 text-white font-black py-4 rounded-xl shadow-lg flex items-center justify-center gap-3">
                      <i className="fas fa-download"></i> BAIXAR
                  </button>
               </div>
           </div>
         )}

         <button onClick={onBack} className="w-full bg-white text-[#a62626] font-bold py-3 rounded-lg border border-red-200">Voltar ao Início</button>
      </div>
    </div>
  );
};

