             <label className="flex items-center gap-2 cursor-pointer"><input type="radio" checked={hymnType === 'coletanea'} onChange={() => setHymnType('coletanea')} /> Coletânea</label>
             <label className="flex items-center gap-2 cursor-pointer"><input type="radio" checked={hymnType === 'cias'} onChange={() => setHymnType('cias')} /> Cias</label>
          </div>
          <div className="relative">
            <input type="text" placeholder="BUSCAR LOUVOR..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value.toUpperCase())} className="w-full pl-4 pr-12 py-3 border border-red-200 rounded-md outline-none text-black uppercase" />
            <button onClick={toggleListening} className={`absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 rounded-full flex items-center justify-center ${isListening ? 'bg-red-600 text-white animate-pulse' : 'text-gray-400'}`}><i className="fas fa-microphone"></i></button>
            {searchResults.length > 0 && (
              <div className="absolute top-full left-0 right-0 bg-white border rounded-md shadow-lg z-10 max-h-48 overflow-y-auto">
                {searchResults.map((h, i) => (
                   <button key={i} onClick={() => selectHymn(h)} className="w-full text-left px-4 py-2 text-sm hover:bg-red-50 flex justify-between border-b uppercase">
                     <span>{h.name}</span><span className="font-bold text-red-500">{h.number}</span>
                   </button>
                ))}
              </div>
            )}
          </div>
        </div>

        <button onClick={clearList} className="mb-4 bg-red-100 text-red-700 px-4 py-2 rounded-md text-xs font-bold uppercase"><i className="fas fa-trash mr-2"></i>Limpar Tudo</button>

        <div className="border border-slate-300 rounded overflow-hidden">
           {rows.map((row, idx) => (
             <div key={idx} className={`flex border-b last:border-0 items-center ${activeRow === idx ? 'bg-blue-50' : 'bg-white'}`}>
                <div className="w-10 border-r flex flex-col items-center bg-slate-50 text-[10px] text-slate-400">
                  <button onClick={() => handleMoveRow(idx, 'up')}><i className="fas fa-chevron-up"></i></button>
                  <button onClick={() => handleMoveRow(idx, 'down')}><i className="fas fa-chevron-down"></i></button>
                </div>
                <input type="text" value={row.number} onChange={(e) => updateRow(idx, 'number', e.target.value)} className="w-16 border-r text-center font-bold p-2 outline-none bg-transparent" placeholder="Nº" />
                <input type="text" value={row.name} onChange={(e) => updateRow(idx, 'name', e.target.value)} className="flex-1 p-2 outline-none uppercase bg-transparent" placeholder="NOME DO HINO" />
             </div>
           ))}
        </div>
      </div>

      <div className="w-full max-w-4xl mt-6 flex flex-col gap-6">
         <button onClick={generateImage} disabled={isGenerating} className="w-full bg-[#dc2626] text-white font-bold py-4 rounded-lg shadow-lg flex items-center justify-center gap-2">
            {isGenerating ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-image"></i>}
            GERAR IMAGEM
         </button>

         {generatedImageUrl && (
           <div id="preview-section" className="bg-white rounded-3xl shadow-2xl p-6 border-2 border-red-50">
               <h3 className="text-[#a62626] font-bold text-xl mb-4 text-center">Conferência Final</h3>
               <div className="bg-slate-50 p-4 rounded-xl flex justify-center mb-6">
                  <img src={generatedImageUrl} alt="Preview" className="max-w-full h-auto shadow-lg border" />
               </div>
               <div className="flex flex-col md:flex-row gap-4">
                  <button onClick={async () => { const res = await fetch(generatedImageUrl); const blob = await res.blob(); const file = new File([blob], "louvores.png", { type: "image/png" }); if (navigator.canShare) await navigator.share({ files: [file] }); }} className="flex-1 bg-[#25d366] text-white font-black py-4 rounded-xl shadow-lg flex items-center justify-center gap-3">
                      <i className="fab fa-whatsapp text-2xl"></i> WHATSAPP
                  </button>
                  <button onClick={() => { const link = document.createElement('a'); link.download = 'louvores.png'; link.href = generatedImageUrl; link.click(); }} className="flex-1 bg-blue-600 text-white font-black py-4 rounded-xl shadow-lg flex items-center justify-center gap-3">
                      <i className="fas fa-download"></i> BAIXAR
                  </button>
               </div>
           </div>
         )}

         <button onClick={onBack} className="w-full bg-white text-[#a62626] font-bold py-3 rounded-lg border border-red-200">Voltar ao Início</button>
      </div>
    </div>
  );
};

