import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.39.7';
import { AppSettings } from '../types';

// Supabase config - Assume que as variáveis de ambiente estarão disponíveis
const supabaseUrl = (window as any).process?.env?.SUPABASE_URL || '';
const supabaseKey = (window as any).process?.env?.SUPABASE_ANON_KEY || '';

const supabase = createClient(supabaseUrl, supabaseKey);

const SETTINGS_ID = 'global_config';

export const fetchRemoteSettings = async (): Promise<AppSettings | null> => {
  try {
    const { data, error } = await supabase
      .from('app_settings')
      .select('config')
      .eq('id', SETTINGS_ID)
      .single();

    if (error) {
      console.warn("Supabase: Tabela não encontrada ou erro na busca. Usando local.");
      return null;
    }
    return data.config as AppSettings;
  } catch (err) {
    console.error("Supabase fail:", err);
    return null;
  }
};

export const saveRemoteSettings = async (settings: AppSettings) => {
  try {
    const { error } = await supabase
      .from('app_settings')
      .upsert({ id: SETTINGS_ID, config: settings, updated_at: new Date() });

    if (error) throw error;
    return true;
  } catch (err) {
    console.error("Erro ao salvar no Supabase:", err);
    return false;
  }
};

