export const fetchRemoteSettings = async (): Promise<AppSettings | null> => {
  if (!supabase) return null;

  try {
    const { data, error } = await supabase
      .from('app_settings')
      .select('config')
      .eq('id', SETTINGS_ID)
      .single();

    if (error) {
      console.warn("Supabase: Tabela app_settings não encontrada ou sem dados. Sincronização global inativa.");
      return null;
    }
    return data.config as AppSettings;
  } catch (err) {
    console.error("Erro na busca remota:", err);
    return null;
  }
};

export const saveRemoteSettings = async (settings: AppSettings) => {
  if (!supabase) {
    console.warn("Supabase não configurado. Alteração salva apenas localmente.");
    return false;
  }

  try {
    const { error } = await supabase
      .from('app_settings')
      .upsert({ 
        id: SETTINGS_ID, 
        config: settings, 
        updated_at: new Date().toISOString() 
      });

    if (error) throw error;
    return true;
  } catch (err) {
    console.error("Erro ao sincronizar com Supabase:", err);
    return false;
  }
};

