// Registro do Service Worker para PWA
// Adicionada verificação de localhost e domínios seguros para evitar erros em ambientes de preview
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    // Só tenta registrar se estiver em HTTPS (exigência do PWA) ou localhost
    const isLocalhost = Boolean(
      window.location.hostname === 'localhost' ||
      window.location.hostname === '[::1]' ||
      window.location.hostname.match(/^127(?:\.(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)){3}$/)
    );

    // No Netlify (produção), window.location.protocol será 'https:'
    if (window.location.protocol === 'https:' || isLocalhost) {
      navigator.serviceWorker.register('/sw.js').then(registration => {
        console.log('PWA: Service Worker registrado com sucesso:', registration.scope);
      }).catch(err => {
        // Silencia o erro se for apenas incompatibilidade de origem no ambiente de desenvolvimento
        if (err.message.includes('origin')) {
          console.warn('PWA: Service Worker não registrado (ambiente de desenvolvimento/sandbox). Funcionará após o deploy no Netlify.');
        } else {
          console.error('PWA: Falha ao registrar SW:', err);
        }
      });
    }
  });
}

