export const fetchGiftsHistory = async () => {
  if (!supabase) return [];
  try {
    const { data, error } = await supabase
      .from('spiritual_gifts')
      .select('*')
      .order('created_at', { ascending: false })
      .limit(20);
    if (error) return [];
    return data.map(item => ({
      name: item.recipient,
      gift: item.gift_type,
      date: new Date(item.created_at).toLocaleString('pt-BR')
    }));
  } catch (err) {
    return [];
  }
};

