  const [adultVisitors, setAdultVisitors] = useState(0);
  const [kidsMembers, setKidsMembers] = useState(0);
  const [kidsVisitors, setKidsVisitors] = useState(0);
  const [pastors, setPastors] = useState(0);
  const [deacons, setDeacons] = useState(0);
  const [workers, setWorkers] = useState(0);
  const [generatedImageUrl, setGeneratedImageUrl] = useState<string | null>(null);
  const [isGenerated, setIsGenerated] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    const savedData = localStorage.getItem('SERVICE_DATA_FORM');
    if (savedData) {
      try {
        const data = JSON.parse(savedData);
        setDate(data.date || new Date().toLocaleDateString('pt-BR'));
        setAssistanceGroup(data.assistanceGroup || '');
        setServiceSelection(data.serviceSelection || 'CULTO À NOITE');
        setCustomServiceText(data.customServiceText || '');
        setGatekeeper(data.gatekeeper || '');
        setPraiseLeader(data.praiseLeader || '');
        setWordLeader(data.wordLeader || '');
        setReadText(data.readText || '');
        setAdultMembers(data.adultMembers || 0);
        setAdultVisitors(data.adultVisitors || 0);
        setKidsMembers(data.kidsMembers || 0);
        setKidsVisitors(data.kidsVisitors || 0);
        setPastors(data.pastors || 0);
        setDeacons(data.deacons || 0);
        setWorkers(data.workers || 0);
      } catch (e) {}
    }
  }, []);

  useEffect(() => {
    const data = {
      date, assistanceGroup, serviceSelection, customServiceText,
      gatekeeper, praiseLeader, wordLeader, readText,
      adultMembers, adultVisitors, kidsMembers, kidsVisitors,
      pastors, deacons, workers
    };
    localStorage.setItem('SERVICE_DATA_FORM', JSON.stringify(data));
  }, [date, assistanceGroup, serviceSelection, customServiceText, gatekeeper, praiseLeader, wordLeader, readText, adultMembers, adultVisitors, kidsMembers, kidsVisitors, pastors, deacons, workers]);

  const totalAdults = adultMembers + adultVisitors;
  const totalKids = kidsMembers + kidsVisitors;
  const grandTotal = totalAdults + totalKids;

  const getFinalServiceName = () => {
    if (serviceSelection === 'OUTROS') return customServiceText.trim().toUpperCase() || 'CULTO ESPECIAL';
    return serviceSelection;
  };

  const getDayOfWeek = () => {
    const d = new Date();
    const days = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];
    return days[d.getDay()];
  };

  const generateImage = async () => {
    setIsSaving(true);

    // Salva no Supabase antes de gerar a imagem
    const reportData = {
      date, assistanceGroup, serviceSelection: getFinalServiceName(),
      gatekeeper, praiseLeader, wordLeader, readText,
      adultMembers, adultVisitors, kidsMembers, kidsVisitors,
      pastors, deacons, workers, grandTotal
    };
    await saveServiceReport(reportData);

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = 1200;
    const height = 1680; 
    canvas.width = width;
    canvas.height = height;
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, width, height);

    const primaryColor = '#8f1919';
    const secondaryColor = '#b91c1c';
    const grayColor = '#374151';
    const lightGray = '#f3f4f6';
    const p = 80; 
    let y = p;

    ctx.fillStyle = primaryColor;
    ctx.font = 'bold 56px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('RELATÓRIO DE CULTO', width / 2, y + 20);
    y += 90;

    ctx.fillStyle = '#fff1f2';
    ctx.fillRect(p, y, width - (p*2), 70);
    ctx.fillStyle = secondaryColor;
    ctx.font = 'bold 32px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(`${getDayOfWeek()} - ${date}`, width / 2, y + 35);
    y += 110;

    const col1 = p;
    const col2 = width / 2 + 30;
    const contentW = (width - (p*2) - 60) / 2;

    const drawInfoBox = (label: string, value: string, x: number, yPos: number, w: number) => {
        ctx.fillStyle = primaryColor;
        ctx.font = 'bold 24px Arial';
        ctx.textAlign = 'left';
        ctx.textBaseline = 'top';
        ctx.fillText(label, x, yPos);
        ctx.fillStyle = '#000000';
        ctx.font = '28px Arial';
        ctx.fillText(value.toUpperCase() || '---', x, yPos + 40);
        ctx.beginPath();
        ctx.moveTo(x, yPos + 80);
        ctx.lineTo(x + w, yPos + 80);
        ctx.strokeStyle = '#d1d5db';
        ctx.lineWidth = 2;
        ctx.stroke();
    }

    drawInfoBox('Grupo de Assistência', assistanceGroup, col1, y, width - (p*2));
    y += 110;
    drawInfoBox('Tipo de Culto', getFinalServiceName(), col1, y, width - (p*2));
    y += 120;

    ctx.fillStyle = primaryColor;
    ctx.font = 'bold 32px Arial';
    ctx.textAlign = 'left';
    ctx.fillText('RESPONSÁVEIS', p, y);
    y += 70;

    drawInfoBox('Portão', gatekeeper, col1, y, contentW);
    drawInfoBox('Louvor', praiseLeader, col2, y, contentW);
    y += 110;
    drawInfoBox('Palavra', wordLeader, col1, y, contentW);
    drawInfoBox('Texto Lido', readText, col2, y, contentW);
    y += 130;

    ctx.fillStyle = primaryColor;
    ctx.font = 'bold 32px Arial';
    ctx.textAlign = 'left';
    ctx.fillText('ESTATÍSTICA DE FREQUÊNCIA', p, y);
    y += 60;

    const rowH = 65;
    const colLabel = p + 20;

    const drawStatRow = (label: string, val: number, isSub?: boolean, isBold?: boolean) => {
        if (!isSub) {
            ctx.fillStyle = lightGray;
            ctx.fillRect(p, y - 5, width - (p*2), rowH - 10);
        }
        ctx.fillStyle = isBold ? '#000' : grayColor;
        ctx.font = isBold ? 'bold 28px Arial' : '26px Arial';
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText(label, colLabel + (isSub ? 40 : 0), y + (rowH/2) - 5);
        ctx.textAlign = 'right';
        ctx.font = 'bold 28px Arial';
        ctx.fillText(val.toString(), width - p - 20, y + (rowH/2) - 5);
        y += rowH;
    }

    drawStatRow('ADULTOS', totalAdults, false, true);
    drawStatRow('Membros', adultMembers, true);
    drawStatRow('Visitantes', adultVisitors, true);
    y += 10;
    drawStatRow('CRIANÇAS', totalKids, false, true);
    drawStatRow('Membros', kidsMembers, true);
    drawStatRow('Visitantes', kidsVisitors, true);
    y += 30;

    ctx.fillStyle = primaryColor;
    ctx.fillRect(p, y, width - (p*2), 90);
    ctx.fillStyle = '#FFFFFF';
    ctx.font = 'bold 36px Arial';
    ctx.textAlign = 'left';
    ctx.fillText('TOTAL GERAL (Adultos + Crianças)', p + 30, y + 45);
    ctx.textAlign = 'right';
    ctx.font = 'bold 56px Arial';
    ctx.fillText(grandTotal.toString(), width - p - 30, y + 45);
    y += 140;

    const drawWorkerStat = (label: string, val: number, x: number) => {
        const wBoxW = (width - (p*2)) / 3;
        ctx.fillStyle = '#f9fafb';
        ctx.strokeStyle = '#e5e7eb';
        ctx.fillRect(x, y, wBoxW - 10, 90);
        ctx.strokeRect(x, y, wBoxW - 10, 90);
        ctx.fillStyle = '#6b7280';
        ctx.font = '18px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(label, x + (wBoxW/2), y + 30);
        ctx.fillStyle = '#000';
        ctx.font = 'bold 36px Arial';
        ctx.fillText(val.toString(), x + (wBoxW/2), y + 70);
    }

    drawWorkerStat('Pastores/Ung.', pastors, p);
    drawWorkerStat('Diáconos', deacons, p + ((width - (p*2)) / 3));
    drawWorkerStat('Obreiros', workers, p + (((width - (p*2)) / 3)*2));

    const footerY = height - 60;
    ctx.beginPath();
    ctx.moveTo(p, footerY - 50);
    ctx.lineTo(width - p, footerY - 50);
    ctx.strokeStyle = '#b91c1c';
    ctx.lineWidth = 4;
    ctx.stroke();
    ctx.fillStyle = '#b91c1c';
    ctx.font = 'bold 32px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('IGREJA CRISTÃ MARANATA', width / 2, footerY);

    setGeneratedImageUrl(canvas.toDataURL());
    setIsGenerated(true);
    setIsSaving(false);
    setTimeout(() => window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' }), 100);
  };

  const handleClear = () => {
    if(window.confirm("Deseja realmente limpar todo o formulário?")) {
        localStorage.removeItem('SERVICE_DATA_FORM');
        setDate(new Date().toLocaleDateString('pt-BR'));
        setServiceSelection('CULTO À NOITE');
        setCustomServiceText('');
        setAssistanceGroup('');
        setGatekeeper('');
        setPraiseLeader('');
        setWordLeader('');
        setReadText('');
        setAdultMembers(0);
        setAdultVisitors(0);
        setKidsMembers(0);
        setKidsVisitors(0);
        setPastors(0);
        setDeacons(0);
        setWorkers(0);
        setGeneratedImageUrl(null);
        setIsGenerated(false);
    }
  };

  const NumberInput = ({ value, onChange }: any) => (
    <div className="flex items-center gap-2">
         <button onClick={() => onChange(Math.max(0, value - 1))} className="w-8 h-8 rounded-full bg-blue-100 text-blue-600 font-bold">-</button>
         <input type="tel" value={value} onFocus={(e) => e.target.select()} onChange={(e) => onChange(parseInt(e.target.value.replace(/\D/g, '') || '0', 10))} className="w-20 text-center border border-blue-200 rounded-md py-1 font-bold text-lg outline-none focus:border-blue-500" />
         <button onClick={() => onChange(value + 1)} className="w-8 h-8 rounded-full bg-blue-100 text-blue-600 font-bold">+</button>
    </div>
  );

  const WorkerInput = ({ value, onChange, colorClass }: any) => (
    <div className="flex items-center gap-2">
         <button onClick={() => onChange(Math.max(0, value - 1))} className={`w-8 h-8 rounded-full ${colorClass} font-bold opacity-70`}>-</button>
         <input type="tel" value={value} onFocus={(e) => e.target.select()} onChange={(e) => onChange(parseInt(e.target.value.replace(/\D/g, '') || '0', 10))} className="w-20 text-center border border-gray-200 rounded-md py-1 font-bold text-lg outline-none" />
         <button onClick={() => onChange(value + 1)} className={`w-8 h-8 rounded-full ${colorClass} font-bold opacity-70`}>+</button>
    </div>
  );

  return (
    <div className="min-h-screen bg-[#ffeeefff] font-sans flex flex-col items-center pt-8 pb-8 px-4">
      <h1 className="text-3xl font-bold text-[#8f1919] mb-6 text-center">Dados do Culto</h1>
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-2xl p-6 md:p-8">
        <div className="mb-6 text-center">
            <label className="block text-[#a62626] font-bold mb-1">Data do Culto</label>
            <input type="text" value={date} onChange={(e) => setDate(e.target.value)} className="border border-red-300 rounded-lg px-4 py-2 text-center font-bold text-lg w-full max-w-xs outline-none" />
            <div className="mt-2 bg-[#fff1f2] py-1 rounded text-[#b91c1c] font-bold text-sm">{getDayOfWeek()} - {date}</div>
        </div>
        <div className="mb-6">
            <label className="block text-[#a62626] font-bold mb-2 text-center">Grupo de Assistência Responsável</label>
            <input type="text" value={assistanceGroup} onChange={(e) => setAssistanceGroup(e.target.value.toUpperCase())} placeholder="NOME DO GRUPO" className="w-full border border-red-300 rounded-lg px-4 py-2 text-center text-sm focus:border-red-500 uppercase outline-none" />
        </div>
        <div className="mb-6">
            <label className="block text-[#a62626] font-bold mb-2 text-center">Tipo de Culto</label>
            <div className="flex gap-2">
                {['EBD', 'CULTO À NOITE', 'OUTROS'].map(type => (
                    <button key={type} onClick={() => setServiceSelection(type as any)} className={`flex-1 py-2 rounded-lg border font-bold text-xs ${serviceSelection === type ? 'bg-red-500 text-white' : 'bg-white text-red-500 border-red-200'}`}>{type}</button>
                ))}
            </div>
            {serviceSelection === 'OUTROS' && (
                <input type="text" value={customServiceText} onChange={(e) => setCustomServiceText(e.target.value.toUpperCase())} placeholder="NOME DO CULTO ESPECIAL" className="mt-3 w-full border border-red-300 rounded-lg px-4 py-2 text-center text-sm font-bold uppercase outline-none" />
            )}
        </div>
        <div className="mb-6">
            <h3 className="text-[#a62626] font-bold mb-3 text-center border-b border-red-100 pb-2">Responsáveis</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {[
                  {label: 'Portão', val: gatekeeper, set: setGatekeeper},
                  {label: 'Louvor', val: praiseLeader, set: setPraiseLeader},
                  {label: 'Palavra', val: wordLeader, set: setWordLeader},
                  {label: 'Texto Lido', val: readText, set: setReadText}
                ].map(item => (
                  <div key={item.label}>
                    <label className="block text-[#a62626] text-xs font-bold mb-1">{item.label}</label>
                    <input type="text" value={item.val} onChange={(e) => item.set(e.target.value.toUpperCase())} placeholder="NOME" className="w-full border border-red-200 rounded-lg px-3 py-2 text-sm uppercase outline-none" />
                  </div>
                ))}
