        </div>
        <div className="mb-6">
            <h3 className="text-[#a62626] font-bold mb-4 text-center border-b border-red-100 pb-2">Participantes</h3>
            <div className="grid grid-cols-2 gap-4 mb-4">
                <div className="border border-blue-200 rounded-xl p-3 flex flex-col items-center bg-blue-50/30">
                    <span className="text-blue-800 text-xs font-bold mb-2 uppercase">Membros (Adultos)</span>
                    <NumberInput value={adultMembers} onChange={setAdultMembers} />
                </div>
                <div className="border border-blue-200 rounded-xl p-3 flex flex-col items-center bg-blue-50/30">
                    <span className="text-blue-800 text-xs font-bold mb-2 uppercase">Visitantes (Adultos)</span>
                    <NumberInput value={adultVisitors} onChange={setAdultVisitors} />
