                <div className="border border-green-200 rounded-xl p-3 flex flex-col items-center bg-green-50/30">
                    <span className="text-green-800 text-xs font-bold mb-2 uppercase">Crianças</span>
                    <NumberInput value={kidsMembers} onChange={setKidsMembers} />
