                <div className="border border-orange-200 rounded-lg p-2 flex flex-col items-center">
                    <span className="text-orange-800 text-[10px] font-bold mb-1">DIÁCONOS</span>
                    <WorkerInput value={deacons} onChange={setDeacons} colorClass="bg-orange-100 text-orange-600" />
