                <div className="border border-blue-200 rounded-lg p-2 flex flex-col items-center">
                    <span className="text-blue-800 text-[10px] font-bold mb-1">OBREIROS</span>
                    <WorkerInput value={workers} onChange={setWorkers} colorClass="bg-blue-100 text-blue-600" />
                </div>
            </div>
        </div>
        <div className="grid grid-cols-3 gap-3">
            <div className="bg-blue-50 border border-blue-200 rounded-lg p-2 text-center">
                <span className="text-blue-800 text-[10px] font-bold block">ADULTOS</span>
                <span className="text-blue-900 text-xl font-bold">{totalAdults}</span>
            </div>
            <div className="bg-green-50 border border-green-200 rounded-lg p-2 text-center">
                <span className="text-green-800 text-[10px] font-bold block">CRIANÇAS</span>
                <span className="text-green-900 text-xl font-bold">{totalKids}</span>
            </div>
            <div className="bg-red-50 border border-red-200 rounded-lg p-2 text-center">
                <span className="text-red-800 text-[10px] font-bold block">TOTAL</span>
                <span className="text-red-900 text-xl font-bold">{grandTotal}</span>
            </div>
        </div>
      </div>
      <div className="w-full max-w-2xl mt-6 flex flex-col gap-4">
         <button onClick={handleClear} className="w-full bg-yellow-600 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2"><i className="fas fa-trash"></i> Limpar Formulário</button>
         <button onClick={generateImage} disabled={isSaving} className={`w-full font-bold py-4 rounded-lg flex items-center justify-center gap-2 text-white ${isSaving ? 'bg-gray-400' : 'bg-[#dc2626]'}`}>
            {isSaving ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-image"></i>}
            {isGenerated ? 'Gerar Novamente' : 'Salvar e Gerar Imagem'}
         </button>
         {generatedImageUrl && (
           <div className="bg-white rounded-xl shadow-lg p-4 animate-fade-in">
               <img src={generatedImageUrl} alt="Preview" className="max-w-full h-auto mb-4 border" />
               <div className="flex gap-4">
                  <button onClick={async () => { const res = await fetch(generatedImageUrl); const blob = await res.blob(); const file = new File([blob], "relatorio.png", {type:"image/png"}); if(navigator.share) navigator.share({files:[file]}) }} className="flex-1 bg-[#25d366] text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2"><i className="fab fa-whatsapp"></i> WhatsApp</button>
                  <button onClick={() => { const link = document.createElement('a'); link.download = 'relatorio.png'; link.href = generatedImageUrl; link.click(); }} className="flex-1 bg-blue-600 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2"><i className="fas fa-download"></i> Baixar</button>
               </div>
           </div>
         )}
         <button onClick={onBack} className="w-full bg-white text-[#a62626] font-bold py-3 rounded-lg border border-red-200 flex items-center justify-center gap-2"><i className="fas fa-arrow-left"></i> Voltar</button>
      </div>
    </div>
  );
};

