import { createClient, SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2.39.7';
import { AppSettings } from '../types';

const supabaseUrl = (window as any).process?.env?.SUPABASE_URL || '';
const supabaseKey = (window as any).process?.env?.SUPABASE_ANON_KEY || '';

let supabase: SupabaseClient | null = null;

if (supabaseUrl && supabaseKey) {
  try {
    supabase = createClient(supabaseUrl, supabaseKey);
  } catch (e) {
    console.error("Erro ao inicializar Supabase:", e);
  }
}

const SETTINGS_ID = 'global_config';

/**
 * Busca as configurações globais (Logo, Ícones, Cabeçalhos) salvas por você.
 */
export const fetchRemoteSettings = async (): Promise<AppSettings | null> => {
  if (!supabase) return null;
  try {
    const { data, error } = await supabase
      .from('app_settings')
      .select('config')
      .eq('id', SETTINGS_ID)
      .single();

    if (error) return null;
    return data.config as AppSettings;
  } catch (err) {
    return null;
  }
};

/**
 * Salva as atualizações de sistema que você fizer na tela de configurações.
 */
export const saveRemoteSettings = async (settings: AppSettings) => {
  if (!supabase) {
    console.warn("Supabase não configurado. As alterações serão salvas apenas localmente.");
    return false;
  }
  try {
    const { error } = await supabase.from('app_settings').upsert({ 
      id: SETTINGS_ID, 
      config: settings, 
      updated_at: new Date().toISOString() 
    });
    return !error;
  } catch (err) {
    console.error("Erro ao salvar configurações no Supabase:", err);
    return false;
  }
};

import React, { useState, useEffect } from 'react';

interface ServiceDataFormProps {
