  };

  const generateImage = async () => {
    setIsGenerating(true);

    // Simula um pequeno delay para feedback visual
    await new Promise(resolve => setTimeout(resolve, 600));

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = 1200;
    const height = 1680; 
    canvas.width = width;
    canvas.height = height;
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, width, height);

    const primaryColor = '#8f1919';
    const secondaryColor = '#b91c1c';
    const grayColor = '#374151';
    const lightGray = '#f3f4f6';
    const p = 80; 
    let y = p;

    ctx.fillStyle = primaryColor;
    ctx.font = 'bold 56px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('RELATÓRIO DE CULTO', width / 2, y + 20);
    y += 90;

    ctx.fillStyle = '#fff1f2';
    ctx.fillRect(p, y, width - (p*2), 70);
    ctx.fillStyle = secondaryColor;
    ctx.font = 'bold 32px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(`${getDayOfWeek()} - ${date}`, width / 2, y + 35);
    y += 110;

    const col1 = p;
    const col2 = width / 2 + 30;
    const contentW = (width - (p*2) - 60) / 2;

    const drawInfoBox = (label: string, value: string, x: number, yPos: number, w: number) => {
        ctx.fillStyle = primaryColor;
        ctx.font = 'bold 24px Arial';
        ctx.textAlign = 'left';
        ctx.textBaseline = 'top';
        ctx.fillText(label, x, yPos);
        ctx.fillStyle = '#000000';
        ctx.font = '28px Arial';
        ctx.fillText(value.toUpperCase() || '---', x, yPos + 40);
        ctx.beginPath();
        ctx.moveTo(x, yPos + 80);
        ctx.lineTo(x + w, yPos + 80);
        ctx.strokeStyle = '#d1d5db';
        ctx.lineWidth = 2;
        ctx.stroke();
    }

    drawInfoBox('Grupo de Assistência', assistanceGroup, col1, y, width - (p*2));
    y += 110;
    drawInfoBox('Tipo de Culto', getFinalServiceName(), col1, y, width - (p*2));
    y += 120;

    ctx.fillStyle = primaryColor;
    ctx.font = 'bold 32px Arial';
    ctx.textAlign = 'left';
    ctx.fillText('RESPONSÁVEIS', p, y);
    y += 70;

    drawInfoBox('Portão', gatekeeper, col1, y, contentW);
    drawInfoBox('Louvor', praiseLeader, col2, y, contentW);
    y += 110;
    drawInfoBox('Palavra', wordLeader, col1, y, contentW);
    drawInfoBox('Texto Lido', readText, col2, y, contentW);
    y += 130;

    ctx.fillStyle = primaryColor;
    ctx.font = 'bold 32px Arial';
    ctx.textAlign = 'left';
    ctx.fillText('ESTATÍSTICA DE FREQUÊNCIA', p, y);
    y += 60;

    const rowH = 65;
    const colLabel = p + 20;

    const drawStatRow = (label: string, val: number, isSub?: boolean, isBold?: boolean) => {
        if (!isSub) {
            ctx.fillStyle = lightGray;
            ctx.fillRect(p, y - 5, width - (p*2), rowH - 10);
        }
        ctx.fillStyle = isBold ? '#000' : grayColor;
        ctx.font = isBold ? 'bold 28px Arial' : '26px Arial';
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText(label, colLabel + (isSub ? 40 : 0), y + (rowH/2) - 5);
        ctx.textAlign = 'right';
        ctx.font = 'bold 28px Arial';
        ctx.fillText(val.toString(), width - p - 20, y + (rowH/2) - 5);
        y += rowH;
    }

    drawStatRow('ADULTOS', totalAdults, false, true);
    drawStatRow('Membros', adultMembers, true);
    drawStatRow('Visitantes', adultVisitors, true);
    y += 10;
    drawStatRow('CRIANÇAS', totalKids, false, true);
    drawStatRow('Membros', kidsMembers, true);
    drawStatRow('Visitantes', kidsVisitors, true);
    y += 30;

    ctx.fillStyle = primaryColor;
    ctx.fillRect(p, y, width - (p*2), 90);
    ctx.fillStyle = '#FFFFFF';
    ctx.font = 'bold 36px Arial';
    ctx.textAlign = 'left';
    ctx.fillText('TOTAL GERAL (Adultos + Crianças)', p + 30, y + 45);
    ctx.textAlign = 'right';
    ctx.font = 'bold 56px Arial';
    ctx.fillText(grandTotal.toString(), width - p - 30, y + 45);
    y += 140;

    const drawWorkerStat = (label: string, val: number, x: number) => {
        const wBoxW = (width - (p*2)) / 3;
        ctx.fillStyle = '#f9fafb';
        ctx.strokeStyle = '#e5e7eb';
        ctx.fillRect(x, y, wBoxW - 10, 90);
        ctx.strokeRect(x, y, wBoxW - 10, 90);
        ctx.fillStyle = '#6b7280';
        ctx.font = '18px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(label, x + (wBoxW/2), y + 30);
        ctx.fillStyle = '#000';
        ctx.font = 'bold 36px Arial';
        ctx.fillText(val.toString(), x + (wBoxW/2), y + 70);
    }

    drawWorkerStat('Pastores/Ung.', pastors, p);
    drawWorkerStat('Diáconos', deacons, p + ((width - (p*2)) / 3));
    drawWorkerStat('Obreiros', workers, p + (((width - (p*2)) / 3)*2));

    const footerY = height - 60;
    ctx.beginPath();
    ctx.moveTo(p, footerY - 50);
    ctx.lineTo(width - p, footerY - 50);
    ctx.strokeStyle = '#b91c1c';
    ctx.lineWidth = 4;
    ctx.stroke();
    ctx.fillStyle = '#b91c1c';
    ctx.font = 'bold 32px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('IGREJA CRISTÃ MARANATA', width / 2, footerY);

    setGeneratedImageUrl(canvas.toDataURL());
    setIsGenerated(true);
    setIsGenerating(false);
    setTimeout(() => window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' }), 100);
  };

  const handleClear = () => {
    if(window.confirm("Deseja realmente limpar todo o formulário?")) {
        localStorage.removeItem('SERVICE_DATA_FORM');
        setDate(new Date().toLocaleDateString('pt-BR'));
        setServiceSelection('CULTO À NOITE');
        setCustomServiceText('');
