        setDeacons(0);
        setWorkers(0);
        setGeneratedImageUrl(null);
        setIsGenerated(false);
    }
  };

  const NumberInput = ({ value, onChange }: any) => (
    <div className="flex items-center gap-2">
         <button onClick={() => onChange(Math.max(0, value - 1))} className="w-8 h-8 rounded-full bg-blue-100 text-blue-600 font-bold">-</button>
         <input type="tel" value={value} onFocus={(e) => e.target.select()} onChange={(e) => onChange(parseInt(e.target.value.replace(/\D/g, '') || '0', 10))} className="w-20 text-center border border-blue-200 rounded-md py-1 font-bold text-lg outline-none focus:border-blue-500" />
         <button onClick={() => onChange(value + 1)} className="w-8 h-8 rounded-full bg-blue-100 text-blue-600 font-bold">+</button>
