            <input type="text" value={assistanceGroup} onChange={(e) => setAssistanceGroup(e.target.value.toUpperCase())} placeholder="NOME DO GRUPO" className="w-full border border-red-300 rounded-lg px-4 py-2 text-center text-sm focus:border-red-500 uppercase outline-none" />
