import React, { useState, useEffect } from 'react';

interface GiftRegistrationProps {
  onBack: () => void;
}

const GiftRegistration: React.FC<GiftRegistrationProps> = ({ onBack }) => {
  const [recipient, setRecipient] = useState('');
  const [giftType, setGiftType] = useState('');
  const [history, setHistory] = useState<{name: string, gift: string, date: string}[]>([]);
  const [loading, setLoading] = useState(false);

  // Carrega histórico local apenas desta sessão do navegador
  useEffect(() => {
    const saved = localStorage.getItem('GIFT_HISTORY_LOCAL');
    if (saved) {
      try {
        setHistory(JSON.parse(saved));
      } catch(e) {}
    }
  }, []);

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!recipient.trim() || !giftType.trim() || loading) return;

    setLoading(true);

    // Pequeno delay para simular processamento
    await new Promise(resolve => setTimeout(resolve, 300));

    const newEntry = {
      name: recipient.toUpperCase(),
      gift: giftType.toUpperCase(),
      date: new Date().toLocaleString('pt-BR')
    };

    const newHistory = [newEntry, ...history].slice(0, 50); // Mantém apenas os últimos 50
    setHistory(newHistory);
    localStorage.setItem('GIFT_HISTORY_LOCAL', JSON.stringify(newHistory));

    setRecipient('');
    setGiftType('');
    setLoading(false);
  };

  const clearHistory = () => {
    if(confirm("Limpar histórico de registros local?")) {
      setHistory([]);
      localStorage.removeItem('GIFT_HISTORY_LOCAL');
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 p-6 flex flex-col items-center">
      <div className="max-w-2xl w-full space-y-8">
        <header className="flex items-center justify-between">
          <button onClick={onBack} className="text-slate-400 hover:text-white transition-colors flex items-center gap-2">
            <i className="fas fa-arrow-left"></i>
            <span>Voltar</span>
          </button>
          <h2 className="text-2xl font-bold text-white">Registro de Dons</h2>
          <div className="w-10"></div>
        </header>

        <form onSubmit={handleRegister} className="bg-slate-900 border border-slate-800 p-6 rounded-3xl space-y-4">
          <div>
            <label className="block text-sm text-slate-400 mb-1 ml-1">Nome do Recebedor</label>
            <input 
              type="text" 
              value={recipient}
              onChange={(e) => setRecipient(e.target.value)}
              placeholder="NOME COMPLETO"
              className="w-full bg-slate-950 border border-slate-800 rounded-2xl px-4 py-3 outline-none focus:border-emerald-500 transition-colors uppercase text-white"
            />
          </div>
          <div>
            <label className="block text-sm text-slate-400 mb-1 ml-1">Dom / Brinde</label>
            <input 
              type="text" 
              value={giftType}
              onChange={(e) => setGiftType(e.target.value)}
              placeholder="EX: DOM DE LÍNGUAS, VISÃO, PALAVRA"
              className="w-full bg-slate-950 border border-slate-800 rounded-2xl px-4 py-3 outline-none focus:border-emerald-500 transition-colors uppercase text-white"
            />
          </div>
          <button 
            type="submit"
            disabled={loading}
            className="w-full bg-emerald-600 hover:bg-emerald-500 text-white font-bold py-4 rounded-2xl transition-all shadow-lg shadow-emerald-500/20 flex items-center justify-center gap-2 disabled:opacity-50"
          >
            {loading ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-plus-circle"></i>}
            Registrar no Sistema
          </button>
        </form>

        <div className="space-y-4">
          <div className="flex justify-between items-center px-1">
            <h3 className="text-lg font-bold text-slate-400 uppercase tracking-wider">Registros Recentes</h3>
            {history.length > 0 && (
              <button onClick={clearHistory} className="text-[10px] text-red-500 font-bold uppercase hover:underline">Limpar</button>
            )}
          </div>

          {history.length === 0 ? (
            <div className="bg-slate-900/50 border border-slate-800 border-dashed rounded-3xl p-12 text-center text-slate-500">
              Nenhum registro encontrado nesta sessão.
            </div>
          ) : (
            <div className="space-y-2">
              {history.map((item, idx) => (
                <div key={idx} className="bg-slate-900 border border-slate-800 p-4 rounded-2xl flex justify-between items-center animate-fade-in">
                  <div>
                    <div className="font-bold text-slate-200">{item.name}</div>
                    <div className="text-sm text-emerald-400 font-medium">{item.gift}</div>
                  </div>
                  <div className="text-xs text-slate-500">{item.date}</div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

