import { createClient, SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2.39.7';
import { AppSettings } from '../types';

// As variáveis process.env.SUPABASE_URL e process.env.SUPABASE_ANON_KEY 
// devem ser configuradas no painel do Netlify para o deploy.
const supabaseUrl = (window as any).process?.env?.SUPABASE_URL || '';
const supabaseKey = (window as any).process?.env?.SUPABASE_ANON_KEY || '';

let supabase: SupabaseClient | null = null;

if (supabaseUrl && supabaseKey) {
  try {
    supabase = createClient(supabaseUrl, supabaseKey);
  } catch (e) {
    console.error("Erro ao inicializar Supabase:", e);
  }
}

const SETTINGS_ID = 'global_config';

/**
 * Busca as configurações globais (Logo, Ícones, Cabeçalhos) no Supabase.
 */
export const fetchRemoteSettings = async (): Promise<AppSettings | null> => {
  if (!supabase) {
    console.warn("Supabase não detectado. Usando padrões locais.");
    return null;
  }
  try {
    const { data, error } = await supabase
      .from('app_settings')
      .select('config')
      .eq('id', SETTINGS_ID)
      .maybeSingle(); // maybeSingle não joga erro se não encontrar nada

    if (error) {
      console.error("Erro Supabase:", error);
      return null;
    }

    return data ? (data.config as AppSettings) : null;
  } catch (err) {
    console.error("Erro ao buscar configurações:", err);
    return null;
  }
};

/**
 * Salva as atualizações de sistema (personalização) no Supabase.
 */
export const saveRemoteSettings = async (settings: AppSettings) => {
  if (!supabase) {
    console.warn("Alterações salvas apenas localmente (Supabase ausente).");
    return false;
  }
  try {
    const { error } = await supabase.from('app_settings').upsert({ 
      id: SETTINGS_ID, 
      config: settings, 
      updated_at: new Date().toISOString() 
    });

    if (error) throw error;
    return true;
  } catch (err) {
    console.error("Erro ao persistir configurações no Supabase:", err);
    return false;
  }
};

