const App: React.FC = () => {
  const [mode, setMode] = useState<AppMode>(AppMode.HOME);

  // Settings State inicializado com localStorage ou padrões
  const [settings, setSettings] = useState<AppSettings>(() => {
    const saved = localStorage.getItem('APP_SETTINGS');
    return saved ? JSON.parse(saved) : DEFAULT_SETTINGS;
  });

  // Sincronização em tempo real com Supabase (Busca as atualizações de sistema)
  useEffect(() => {
    const syncWithCloud = async () => {
      const remoteData = await fetchRemoteSettings();
      if (remoteData) {
        setSettings(remoteData);
        localStorage.setItem('APP_SETTINGS', JSON.stringify(remoteData));
      }
    };
    syncWithCloud();
  }, []);

  // Update Settings (Chamado apenas pelo Admin na tela de Settings)
  const handleUpdateSettings = async (newSettings: AppSettings) => {
    setSettings(newSettings);
    localStorage.setItem('APP_SETTINGS', JSON.stringify(newSettings));
    await saveRemoteSettings(newSettings);
  };

  // Chat State
  const [messages, setMessages] = useState<ChatMessage[]>([
    { id: '1', role: MessageRole.MODEL, text: 'Paz do Senhor! Sou o assistente de suporte técnico. Como posso ajudar você a usar as ferramentas do sistema hoje?' }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = async () => {
    if ((!input.trim() && !selectedFile) || loading) return;

    let imageBase64: string | undefined;
    if (selectedFile) {
      imageBase64 = await fileToBase64(selectedFile);
    }

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: MessageRole.USER,
      text: input,
      image: imageBase64
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setSelectedFile(null);
    setLoading(true);

    try {
      const response = await sendMessageToGemini(userMsg.text || "Como este sistema funciona?", imageBase64);
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: MessageRole.MODEL,
        text: response.text,
        groundingSources: response.sources
      }]);
    } catch (err: any) {
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: MessageRole.MODEL,
        text: 'Desculpe, tive um problema técnico ao acessar o guia do sistema.',
        isError: true
      }]);
    } finally {
      setLoading(false);
    }
  };

  const renderContent = () => {
    switch (mode) {
      case AppMode.LOGIN:
        return <LoginScreen onSuccess={() => setMode(AppMode.SETTINGS)} onBack={() => setMode(AppMode.HOME)} />;
      case AppMode.SETTINGS:
        return <SettingsScreen settings={settings} onUpdate={handleUpdateSettings} onBack={() => setMode(AppMode.HOME)} />;
      case AppMode.HYMN_LIST:
        return <HymnManager settings={settings} onBack={() => setMode(AppMode.HOME)} />;
      case AppMode.GIFT_REGISTRATION:
        return <GiftRegistration onBack={() => setMode(AppMode.HOME)} />;
      case AppMode.OTHER_APPS_MENU:
        return <OtherAppsMenu onBack={() => setMode(AppMode.HOME)} onNavigateToServiceData={() => setMode(AppMode.SERVICE_DATA)} />;
      case AppMode.SERVICE_DATA:
        return <ServiceDataForm onBack={() => setMode(AppMode.OTHER_APPS_MENU)} />;
      case AppMode.LIVE:
        return <LiveInterface onBack={() => setMode(AppMode.CHAT)} />;
      case AppMode.CHAT:
        return (
          <div className="flex flex-col h-screen bg-[#fff5f5] animate-fade-in">
            <header className="flex items-center justify-between p-4 border-b border-red-100 bg-white shadow-sm z-10">
              <button onClick={() => setMode(AppMode.HOME)} className="text-[#8f1919] hover:text-red-800 p-2">
                <i className="fas fa-chevron-left text-xl"></i>
              </button>
              <div className="text-center">
                <h2 className="text-lg font-bold text-[#8f1919]">Suporte Técnico</h2>
                <span className="text-[10px] text-red-500 font-bold uppercase tracking-widest">Guia do Aplicativo</span>
              </div>
              <button onClick={() => setMode(AppMode.LIVE)} className="bg-[#8f1919] text-white w-10 h-10 rounded-full flex items-center justify-center shadow-lg hover:scale-110 transition-transform">
                <i className="fas fa-headset"></i>
              </button>
            </header>

            <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-transparent">
              <div className="max-w-3xl mx-auto">
                {messages.map(m => <ChatBubble key={m.id} message={m} />)}
                {loading && (
                  <div className="flex justify-start mb-4">
                    <div className="bg-white border border-red-100 p-4 rounded-2xl rounded-tl-none flex gap-1 shadow-sm">
                      <div className="w-2 h-2 bg-red-400 rounded-full animate-bounce"></div>
                      <div className="w-2 h-2 bg-red-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                      <div className="w-2 h-2 bg-red-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                    </div>
                  </div>
                )}
                <div ref={scrollRef} />
              </div>
            </div>

            <footer className="p-4 bg-white border-t border-red-100">
              <div className="max-w-3xl mx-auto">
                <div className="flex items-end gap-2">
                  <textarea 
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                    placeholder="Ex: Como gerar o cartaz de louvores?"
                    className="flex-1 bg-red-50 border border-red-100 rounded-xl p-3 text-slate-800 placeholder-red-300 resize-none focus:ring-2 focus:ring-red-500 focus:bg-white outline-none max-h-32"
                    rows={1}
                  />
                  <button onClick={handleSendMessage} disabled={loading} className="p-3 bg-[#8f1919] text-white rounded-xl hover:bg-red-800 disabled:opacity-50 shadow-md transition-all">
                    <i className="fas fa-paper-plane text-xl"></i>
                  </button>
                </div>
              </div>
            </footer>
          </div>
        );
      default:
        return (
          <HomeScreen 
            settings={settings}
            onNavigateToChat={() => setMode(AppMode.CHAT)} 
            onNavigateToHymns={() => setMode(AppMode.HYMN_LIST)}
            onNavigateToGifts={() => setMode(AppMode.GIFT_REGISTRATION)}
            onNavigateToOtherSystems={() => setMode(AppMode.OTHER_APPS_MENU)}
            onNavigateToSettings={() => setMode(AppMode.LOGIN)}
          />
        );
    }
  };

  return <div className="min-h-screen text-slate-800">{renderContent()}</div>;
};

