          <button onClick={onBack} className="w-full bg-white border border-red-400 text-red-600 font-bold py-4 rounded-2xl shadow-md flex items-center justify-center gap-2">
            <i className="fas fa-arrow-left"></i> Voltar ao Início
          </button>
        </div>
      </div>
    );
  }

  // TELA DE EDIÇÃO (EDIT)
  return (
    <div className="min-h-screen bg-[#fff5f5] p-4 flex flex-col items-center animate-fade-in">
      <div className="max-w-lg w-full">
