              <label className="flex items-center gap-2 text-xs font-bold text-red-700 cursor-pointer">
                <input 
                  type="checkbox" 
                  checked={includeDate} 
                  onChange={(e) => setIncludeDate(e.target.checked)}
                  className="w-4 h-4 accent-red-600"
                />
                Incluir data na imagem
