                  <input 
                    type="date" 
                    value={giftDate}
                    onChange={(e) => setGiftDate(e.target.value)}
                    className="w-full border border-red-200 rounded-xl p-3 text-sm outline-none"
                  />
                </div>
              )}
            </div>

            {/* Formatação */}
            <div className="space-y-2 py-2">
              <label className="flex items-center gap-2 text-xs font-bold text-red-700 cursor-pointer">
                <input type="checkbox" checked={isJustified} onChange={(e) => setIsJustified(e.target.checked)} className="w-4 h-4 accent-red-600" />
