import React, { useState, useEffect, useRef } from 'react';

interface GiftRegistrationProps {
  onBack: () => void;
}

type GiftCategory = 'SONHO' | 'VISÃO' | 'REVELAÇÃO' | 'OUTROS';

const GiftRegistration: React.FC<GiftRegistrationProps> = ({ onBack }) => {
  // Estados de Fluxo
  const [step, setStep] = useState<'SELECT' | 'EDIT'>('SELECT');
  const [category, setCategory] = useState<GiftCategory>('SONHO');

  // Estados do Formulário
  const [churchName, setChurchName] = useState('');
  const [includeDate, setIncludeDate] = useState(true);
  const [giftDate, setGiftDate] = useState(new Date().toISOString().split('T')[0]);
  const [isJustified, setIsJustified] = useState(false);
  const [isVertical, setIsVertical] = useState(false);
  const [fontSize, setFontSize] = useState(24);
  const [content, setContent] = useState('');

  // Estados de UI
  const [isListening, setIsListening] = useState(false);
  const [generatedImageUrl, setGeneratedImageUrl] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const recognitionRef = useRef<any>(null);

  // Inicializa reconhecimento de voz
  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.continuous = true;
      recognition.interimResults = true;
      recognition.lang = 'pt-BR';
      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);
      recognition.onresult = (event: any) => {
        let transcript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) transcript += event.results[i][0].transcript;
        }
        if (transcript) {
          setContent(prev => prev + (prev ? ' ' : '') + transcript);
        }
      };
      recognitionRef.current = recognition;
    }
  }, []);

  const toggleListening = () => {
    if (!recognitionRef.current) return alert("Reconhecimento de voz não suportado.");
    isListening ? recognitionRef.current.stop() : recognitionRef.current.start();
  };

  const handleSelectCategory = (cat: GiftCategory) => {
    setCategory(cat);
    setStep('EDIT');
  };

  const generateGiftImage = async () => {
    setIsGenerating(true);
    await new Promise(r => setTimeout(r, 800));

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = isVertical ? 1080 : 1200;
    const height = isVertical ? 1920 : 1200;
    canvas.width = width;
    canvas.height = height;

    // Fundo
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, width, height);

    // Borda/Moldura
    ctx.strokeStyle = '#8f1919';
    ctx.lineWidth = 15;
    ctx.strokeRect(30, 30, width - 60, height - 60);

    let currentY = 150;

    // Título da Categoria
    ctx.fillStyle = '#8f1919';
    ctx.font = 'bold 80px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(category, width / 2, currentY);
    currentY += 80;

    // Nome da Igreja
    if (churchName) {
      ctx.font = 'italic 35px Arial';
      ctx.fillStyle = '#b91c1c';
      ctx.fillText(churchName, width / 2, currentY);
      currentY += 50;
    }

    // Data
    if (includeDate) {
      const formattedDate = new Date(giftDate).toLocaleDateString('pt-BR');
      ctx.font = '30px Arial';
      ctx.fillStyle = '#b91c1c';
      ctx.fillText(formattedDate, width / 2, currentY);
      currentY += 80;
    }

    // Conteúdo com respeito a quebras de linha manuais
    ctx.fillStyle = '#1a1a1a';
    const drawFontSize = fontSize * 1.8;
    ctx.font = `${drawFontSize}px Arial, "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji"`;
    ctx.textAlign = 'center';

    const maxWidth = width - 240;
    const lineHeight = drawFontSize * 1.4;

    // Divide o conteúdo pelas quebras de linha manuais (\n)
    const paragraphs = content.split('\n');

    paragraphs.forEach((paragraph) => {
      if (paragraph.trim() === "") {
        currentY += lineHeight; // Pula linha se for parágrafo vazio
        return;
      }

      const words = paragraph.split(' ');
      let line = '';

      for (let n = 0; n < words.length; n++) {
        const testLine = line + words[n] + ' ';
        const metrics = ctx.measureText(testLine);
        if (metrics.width > maxWidth && n > 0) {
          ctx.fillText(line.trim(), width / 2, currentY);
          line = words[n] + ' ';
          currentY += lineHeight;
        } else {
          line = testLine;
        }
      }
      ctx.fillText(line.trim(), width / 2, currentY);
      currentY += lineHeight; // Espaço após cada parágrafo
    });

    // Rodapé
    ctx.font = 'bold 22px Arial';
    ctx.fillStyle = '#8f1919';
    ctx.fillText('ICM PLANALTO - LINHARES/ES', width / 2, height - 80);

    setGeneratedImageUrl(canvas.toDataURL('image/png'));
    setIsGenerating(false);
  };

  if (step === 'SELECT') {
    return (
      <div className="min-h-screen bg-[#fff5f5] p-6 flex flex-col items-center animate-fade-in">
        <div className="max-w-md w-full flex flex-col items-center">
          <h1 className="text-4xl font-bold text-[#8f1919] mb-8 text-center">Registro de Dons</h1>
          <div className="w-full bg-white rounded-[2rem] shadow-xl p-8 mb-6 border border-red-50">
            <h2 className="text-[#8f1919] font-bold text-xl text-center mb-8 tracking-wider">O QUE VAMOS ESCREVER?</h2>
            <div className="space-y-4">
              {(['SONHO', 'VISÃO', 'REVELAÇÃO', 'OUTROS'] as GiftCategory[]).map((option) => (
                <button
                  key={option}
                  onClick={() => handleSelectCategory(option)}
                  className="w-full py-5 rounded-2xl border border-red-200 text-[#8f1919] font-bold text-xl hover:bg-red-50 active:scale-[0.98] transition-all"
                >
                  {option}
                </button>
              ))}
            </div>
          </div>
          <button onClick={onBack} className="w-full bg-white border border-red-400 text-red-600 font-bold py-4 rounded-2xl shadow-md flex items-center justify-center gap-2">
            <i className="fas fa-arrow-left"></i> Voltar ao Início
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#fff5f5] p-4 flex flex-col items-center animate-fade-in">
      <div className="max-w-lg w-full">
        <h1 className="text-3xl font-bold text-[#8f1919] mb-6 text-center">Registro de Dons</h1>

        <div className="bg-white rounded-[2rem] shadow-xl p-6 mb-6 border border-red-50 flex flex-col">
          <div className="flex justify-center mb-6">
            <button className="px-10 py-2 border-2 border-red-200 rounded-xl text-[#8f1919] font-bold text-xl uppercase bg-white">
              {category}
            </button>
          </div>

          <h2 className="text-[#8f1919] font-bold text-xl text-center mb-6">
            Escreva aqui o {category.toLowerCase()}
          </h2>

          <div className="space-y-4">
            <div>
              <label className="text-[10px] font-bold text-red-700 uppercase ml-1 block mb-1">Nome da Igreja (opcional):</label>
              <input 
                type="text" 
                placeholder="Ex: Planalto Linhares"
                value={churchName}
                onChange={(e) => setChurchName(e.target.value)}
                className="w-full border border-red-200 rounded-xl p-3 text-sm focus:ring-2 focus:ring-red-100 outline-none bg-white text-slate-800"
              />
            </div>

            <div className="flex flex-col gap-2">
              <label className="flex items-center gap-2 text-xs font-bold text-red-700 cursor-pointer">
                <input type="checkbox" checked={includeDate} onChange={(e) => setIncludeDate(e.target.checked)} className="w-4 h-4 accent-red-600" />
                Incluir data na imagem
              </label>
              {includeDate && (
                <div>
                  <label className="text-[10px] font-bold text-red-700 uppercase ml-1 block mb-1">Escolher data:</label>
                  <input type="date" value={giftDate} onChange={(e) => setGiftDate(e.target.value)} className="w-full border border-red-200 rounded-xl p-3 text-sm outline-none bg-white text-slate-800" />
                </div>
              )}
            </div>

            <div className="space-y-2 py-2">
              <label className="flex items-center gap-2 text-xs font-bold text-red-700 cursor-pointer">
                <input type="checkbox" checked={isVertical} onChange={(e) => setIsVertical(e.target.checked)} className="w-4 h-4 accent-red-600" />
                <i className="fas fa-mobile-alt"></i> Imagem vertical (melhor para celular)
              </label>
            </div>

            <div className="flex items-center justify-center gap-4 py-2">
              <span className="text-xs font-bold text-red-700">Tamanho da fonte:</span>
              <button onClick={() => setFontSize(f => Math.max(12, f - 2))} className="w-8 h-8 rounded-full bg-red-100 text-red-700 flex items-center justify-center font-bold">-</button>
              <span className="font-bold text-red-900">{fontSize}px</span>
              <button onClick={() => setFontSize(f => Math.min(60, f + 2))} className="w-8 h-8 rounded-full bg-red-100 text-red-700 flex items-center justify-center font-bold">+</button>
            </div>

            <div className="relative">
              <textarea 
                placeholder="Escreva aqui..."
                value={content}
                onChange={(e) => setContent(e.target.value)}
                className="w-full min-h-[200px] border border-red-200 rounded-2xl p-4 focus:ring-2 focus:ring-red-100 outline-none bg-white text-slate-800 leading-relaxed shadow-inner"
                style={{ fontSize: `${fontSize}px` }}
              />
              <button 
                onClick={toggleListening}
                className={`absolute bottom-4 right-4 w-12 h-12 rounded-full shadow-lg flex items-center justify-center transition-all ${isListening ? 'bg-red-600 text-white animate-pulse' : 'bg-red-50 text-red-600 hover:bg-red-100'}`}
              >
                <i className={`fas ${isListening ? 'fa-stop' : 'fa-microphone'} text-xl`}></i>
              </button>
            </div>
          </div>
        </div>

        <div className="space-y-4 mb-10">
          <button 
            onClick={generateGiftImage}
            disabled={!content || isGenerating}
            className="w-full bg-slate-500 hover:bg-slate-600 text-white font-bold py-4 rounded-2xl shadow-lg flex items-center justify-center gap-2 transition-all disabled:opacity-50"
          >
            {isGenerating ? <i className="fas fa-circle-notch animate-spin"></i> : <i className="fas fa-image"></i>}
            Gerar Imagem
          </button>

          <button onClick={() => setStep('SELECT')} className="w-full bg-white border border-red-400 text-red-600 font-bold py-4 rounded-2xl shadow-md flex items-center justify-center gap-2">
            <i className="fas fa-arrow-left"></i> Voltar
          </button>
        </div>

        {generatedImageUrl && (
          <div className="bg-white rounded-[2rem] shadow-2xl p-6 border-2 border-red-50 mb-10 animate-fade-in">
            <h3 className="text-[#8f1919] font-bold text-xl mb-4 text-center uppercase tracking-widest">Imagem Gerada</h3>
            <img src={generatedImageUrl} alt="Preview" className="w-full rounded-xl border mb-6 shadow-sm" />
            <div className="flex gap-4">
              <button 
                onClick={async () => {
                  const res = await fetch(generatedImageUrl);
                  const blob = await res.blob();
                  const file = new File([blob], "dom_icm.png", { type: "image/png" });
                  if (navigator.share) await navigator.share({ files: [file] });
                }}
                className="flex-1 bg-[#25d366] text-white font-black py-4 rounded-xl shadow-lg flex items-center justify-center gap-3 active:scale-95 transition-all"
              >
                <i className="fab fa-whatsapp text-2xl"></i> WHATSAPP
              </button>
              <button 
                onClick={() => {
                  const link = document.createElement('a');
                  link.download = `dom_icm.png`;
                  link.href = generatedImageUrl;
                  link.click();
                }}
                className="flex-1 bg-blue-600 text-white font-black py-4 rounded-xl shadow-lg flex items-center justify-center gap-3 active:scale-95 transition-all"
              >
                <i className="fas fa-download"></i> BAIXAR
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

