  const [giftDate, setGiftDate] = useState(new Date().toISOString().split('T')[0]);
  const [isVertical, setIsVertical] = useState(true);
  const [textAlign, setTextAlign] = useState<TextAlign>('left');
  const [fontSize, setFontSize] = useState(24);
  const [content, setContent] = useState('');

  // Estados de UI
  const [isListening, setIsListening] = useState(false);
  const [generatedImageUrl, setGeneratedImageUrl] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.continuous = true;
      recognition.interimResults = true;
      recognition.lang = 'pt-BR';
      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);
      recognition.onresult = (event: any) => {
        let transcript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) transcript += event.results[i][0].transcript;
        }
        if (transcript) {
          setContent(prev => prev + (prev ? ' ' : '') + transcript);
        }
      };
      recognitionRef.current = recognition;
    }
  }, []);

  const toggleListening = () => {
    if (!recognitionRef.current) return alert("Reconhecimento de voz não suportado.");
    isListening ? recognitionRef.current.stop() : recognitionRef.current.start();
  };

  const handleSelectCategory = (cat: GiftCategory) => {
    setCategory(cat);
    setStep('EDIT');
  };

  const generateGiftImage = async () => {
    setIsGenerating(true);
    await new Promise(r => setTimeout(r, 800));

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = isVertical ? 1080 : 1920;
    const drawFontSize = fontSize * 1.8;
    const lineHeight = drawFontSize * 1.4;
    const marginX = 120; 
    const maxWidth = width - (marginX * 2);

    ctx.font = `${drawFontSize}px Arial, "Apple Color Emoji", "Segoe UI Emoji"`;

    // Cálculo de linhas para altura dinâmica
    const paragraphs = content.split('\n');
    let totalTextLines = 0;
    const wrappedParagraphs: string[][] = [];

    paragraphs.forEach(p => {
      const lines: string[] = [];
      if (p.trim() === "") {
        lines.push("");
        totalTextLines += 1;
      } else {
        const words = p.split(' ');
        let currentLine = '';
        for (let n = 0; n < words.length; n++) {
          const testLine = currentLine + words[n] + ' ';
          const metrics = ctx.measureText(testLine);
          if (metrics.width > maxWidth && n > 0) {
            lines.push(currentLine.trim());
            currentLine = words[n] + ' ';
            totalTextLines += 1;
          } else {
            currentLine = testLine;
          }
        }
        lines.push(currentLine.trim());
        totalTextLines += 1;
      }
      wrappedParagraphs.push(lines);
    });

    const footerSpace = 300; 
    const headerSpace = 450; 
