    ctx.font = `${drawFontSize}px Arial, "Apple Color Emoji", "Segoe UI Emoji"`;

    wrappedParagraphs.forEach((lines) => {
      lines.forEach((line, idx) => {
        if (line === "") {
          currentY += lineHeight;
          return;
        }

        const isLastLine = idx === lines.length - 1;
        const xPos = textAlign === 'center' ? width / 2 : (textAlign === 'left' || textAlign === 'justify' ? marginX : width / 2);
        ctx.textAlign = textAlign === 'justify' ? 'left' : textAlign;

        if (textAlign === 'justify' && !isLastLine) {
          const words = line.split(' ');
          if (words.length > 1) {
            const totalWordsWidth = words.reduce((acc, w) => acc + ctx.measureText(w).width, 0);
            const totalSpacing = maxWidth - totalWordsWidth;
            const spaceWidth = totalSpacing / (words.length - 1);
            let startX = marginX;
            words.forEach((word) => {
              ctx.fillText(word, startX, currentY);
              startX += ctx.measureText(word).width + spaceWidth;
            });
          } else {
            ctx.fillText(line, xPos, currentY);
          }
        } else {
          // Ajuste para centralizado e esquerda
          const drawX = textAlign === 'center' ? width / 2 : marginX;
          ctx.fillText(line, drawX, currentY);
        }
        currentY += lineHeight;
      });
      currentY += lineHeight * 0.3; // Pequeno respiro entre parágrafos
    });

    // Rodapé Dinâmico
