            <h2 className="text-[#8f1919] font-bold text-xl mb-8 tracking-wider uppercase">O que vamos registrar?</h2>
            <div className="space-y-4">
              {(['SONHO', 'VISÃO', 'REVELAÇÃO', 'OUTROS'] as GiftCategory[]).map((option) => (
                <button
                  key={option}
                  onClick={() => handleSelectCategory(option)}
                  className="w-full py-5 rounded-2xl border border-red-200 text-[#8f1919] font-bold text-xl hover:bg-red-50 active:scale-95 transition-all"
                >
                  {option}
                </button>
              ))}
            </div>
          </div>
          <button onClick={onBack} className="w-full bg-white border border-red-400 text-red-600 font-bold py-4 rounded-2xl shadow-md flex items-center justify-center gap-2">
            <i className="fas fa-arrow-left"></i> Voltar ao Início
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#fff5f5] p-4 flex flex-col items-center animate-fade-in">
      <div className="max-w-lg w-full">
        <h1 className="text-3xl font-bold text-[#8f1919] mb-6 text-center">Registro de Dons</h1>

        <div className="bg-white rounded-[2rem] shadow-xl p-6 mb-6 border border-red-50 flex flex-col">
          <div className="flex justify-center mb-6">
            <button className="px-10 py-2 border-2 border-red-200 rounded-xl text-[#8f1919] font-bold text-xl uppercase bg-white">
              {category}
            </button>
          </div>

          <div className="space-y-5">
            <div>
              <label className="text-[10px] font-bold text-red-700 uppercase ml-1 block mb-1">Nome da Igreja (opcional):</label>
              <input 
                type="text" 
                placeholder="Ex: Planalto Linhares - ES"
                value={churchName}
                onChange={(e) => setChurchName(e.target.value)}
                className="w-full border border-red-200 rounded-xl p-3 text-sm focus:ring-2 focus:ring-red-100 outline-none bg-white text-slate-800"
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
               <div className="flex flex-col gap-2">
                 <label className="text-[10px] font-bold text-red-700 uppercase ml-1">Data:</label>
                 <input type="date" value={giftDate} onChange={(e) => setGiftDate(e.target.value)} className="w-full border border-red-200 rounded-xl p-3 text-xs outline-none bg-white" />
               </div>
               <div className="flex flex-col gap-2 justify-end pb-2">
                  <label className="flex items-center gap-2 text-[11px] font-bold text-red-700 cursor-pointer">
                    <input type="checkbox" checked={includeDate} onChange={(e) => setIncludeDate(e.target.checked)} className="w-4 h-4 accent-red-600" />
