                  </label>
               </div>
            </div>

            <div className="border-t border-red-50 pt-4">
              <label className="text-[10px] font-bold text-red-700 uppercase ml-1 block mb-2">Formatação e Orientação:</label>
              <div className="flex flex-wrap gap-2 mb-4">
                 <button 
                  onClick={() => setIsVertical(true)}
                  className={`flex-1 py-2 rounded-lg text-[10px] font-bold border transition-all ${isVertical ? 'bg-red-600 text-white border-red-600' : 'bg-white text-red-600 border-red-200'}`}
