                   >
                     <i className={`fas fa-align-${align === 'justify' ? 'justify' : align}`}></i>
                   </button>
                 ))}
              </div>
            </div>

            <div className="flex items-center justify-between px-2">
              <span className="text-[10px] font-bold text-red-700 uppercase">Tamanho da Fonte:</span>
              <div className="flex items-center gap-3">
                <button onClick={() => setFontSize(f => Math.max(12, f - 2))} className="w-7 h-7 rounded-full bg-red-50 text-red-700 flex items-center justify-center">-</button>
                <span className="font-bold text-red-900 text-sm">{fontSize}px</span>
                <button onClick={() => setFontSize(f => Math.min(60, f + 2))} className="w-7 h-7 rounded-full bg-red-50 text-red-700 flex items-center justify-center">+</button>
              </div>
            </div>

            <div className="relative">
              <textarea 
                placeholder={`Escreva aqui o ${category.toLowerCase()}...`}
                value={content}
                onChange={(e) => setContent(e.target.value)}
                className={`w-full min-h-[250px] border border-red-200 rounded-2xl p-4 focus:ring-2 focus:ring-red-100 outline-none bg-white text-slate-800 leading-relaxed shadow-sm whitespace-pre-wrap ${textAlign === 'center' ? 'text-center' : (textAlign === 'justify' ? 'text-justify' : 'text-left')}`}
                style={{ fontSize: `${fontSize}px` }}
              />
              <button 
                onClick={toggleListening}
                className={`absolute bottom-4 right-4 w-12 h-12 rounded-full shadow-lg flex items-center justify-center transition-all ${isListening ? 'bg-red-600 text-white animate-pulse' : 'bg-red-50 text-red-600 hover:bg-red-100'}`}
              >
                <i className={`fas ${isListening ? 'fa-stop' : 'fa-microphone'} text-xl`}></i>
              </button>
            </div>
          </div>
        </div>

        <div className="space-y-4 mb-10">
          <button 
            onClick={generateGiftImage}
            disabled={!content || isGenerating}
            className="w-full bg-slate-600 hover:bg-slate-700 text-white font-bold py-4 rounded-2xl shadow-lg flex items-center justify-center gap-2 transition-all disabled:opacity-50"
          >
            {isGenerating ? <i className="fas fa-circle-notch animate-spin"></i> : <i className="fas fa-magic"></i>}
            Gerar Imagem
          </button>

          <button onClick={() => setStep('SELECT')} className="w-full bg-white border border-red-400 text-red-600 font-bold py-4 rounded-2xl shadow-md flex items-center justify-center gap-2">
            <i className="fas fa-arrow-left"></i> Escolher Outra Categoria
          </button>
        </div>

        {generatedImageUrl && (
          <div className="bg-white rounded-[2rem] shadow-2xl p-6 border-2 border-red-50 mb-10 animate-fade-in">
            <h3 className="text-[#8f1919] font-bold text-xl mb-4 text-center uppercase tracking-widest">Imagem Gerada</h3>
            <div className="rounded-xl overflow-hidden border border-red-100 bg-gray-50 mb-6">
              <img src={generatedImageUrl} alt="Preview" className="w-full h-auto" />
            </div>
            <div className="flex gap-4">
              <button 
                onClick={async () => {
                  const res = await fetch(generatedImageUrl);
                  const blob = await res.blob();
                  const file = new File([blob], "dom_icm.png", { type: "image/png" });
                  if (navigator.share) await navigator.share({ files: [file] });
