import React, { useState, useEffect, useRef } from 'react';

interface GiftRegistrationProps {
  onBack: () => void;
}

type GiftCategory = 'SONHO' | 'VISÃO' | 'REVELAÇÃO' | 'OUTROS';
type TextAlign = 'left' | 'center' | 'justify';

const GiftRegistration: React.FC<GiftRegistrationProps> = ({ onBack }) => {
  // Estados de Fluxo
  const [step, setStep] = useState<'SELECT' | 'EDIT'>('SELECT');
  const [category, setCategory] = useState<GiftCategory>('SONHO');

  // Estados do Formulário
  const [churchName, setChurchName] = useState('');
  const [includeDate, setIncludeDate] = useState(true);
  const [giftDate, setGiftDate] = useState(new Date().toISOString().split('T')[0]);
  const [isVertical, setIsVertical] = useState(true);
  const [textAlign, setTextAlign] = useState<TextAlign>('left');
  const [fontSize, setFontSize] = useState(24);
  const [content, setContent] = useState('');

  // Estados de UI
  const [isListening, setIsListening] = useState(false);
  const [generatedImageUrl, setGeneratedImageUrl] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.continuous = true;
      recognition.interimResults = true;
      recognition.lang = 'pt-BR';
      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);
      recognition.onresult = (event: any) => {
        let transcript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) transcript += event.results[i][0].transcript;
        }
        if (transcript) {
          setContent(prev => prev + (prev ? ' ' : '') + transcript);
        }
      };
      recognitionRef.current = recognition;
    }
  }, []);

  const toggleListening = () => {
    if (!recognitionRef.current) return alert("Reconhecimento de voz não suportado.");
    isListening ? recognitionRef.current.stop() : recognitionRef.current.start();
  };

  const handleSelectCategory = (cat: GiftCategory) => {
    setCategory(cat);
    setStep('EDIT');
  };

  const generateGiftImage = async () => {
    setIsGenerating(true);
    await new Promise(r => setTimeout(r, 800));

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Define dimensões base de acordo com a orientação
    // Vertical: 1080x1920 (Portait) | Horizontal: 1920x1080 (Landscape)
    const baseWidth = isVertical ? 1080 : 1920;
    const baseHeight = isVertical ? 1920 : 1080;

    const drawFontSize = fontSize * 2.2; // Escala para legibilidade em alta resolução
    const lineHeight = drawFontSize * 1.5;
    const marginX = 150; // Margem de segurança lateral maior
    const maxWidth = baseWidth - (marginX * 2);

    ctx.font = `${drawFontSize}px Arial, "Apple Color Emoji", "Segoe UI Emoji"`;

    // Cálculo de linhas para altura dinâmica (se o texto exceder a altura base)
    const paragraphs = content.split('\n');
    let totalTextLines = 0;
    const wrappedParagraphs: string[][] = [];

    paragraphs.forEach(p => {
      const lines: string[] = [];
      if (p.trim() === "") {
        lines.push("");
        totalTextLines += 1;
      } else {
        const words = p.split(' ');
        let currentLine = '';
        for (let n = 0; n < words.length; n++) {
          const testLine = currentLine + words[n] + ' ';
          const metrics = ctx.measureText(testLine);
          // Se ultrapassar o limite de largura, quebra a linha
          if (metrics.width > maxWidth) {
            lines.push(currentLine.trim());
            currentLine = words[n] + ' ';
            totalTextLines += 1;
          } else {
            currentLine = testLine;
          }
        }
        lines.push(currentLine.trim());
        totalTextLines += 1;
      }
      wrappedParagraphs.push(lines);
    });

    const headerSpace = 400; 
    const footerSpace = 300; 
    const dynamicRequiredHeight = headerSpace + (totalTextLines * lineHeight) + footerSpace;
    const height = Math.max(baseHeight, dynamicRequiredHeight);
    const width = baseWidth;

    canvas.width = width;
    canvas.height = height;

    // Fundo
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, width, height);

    // MOLDURA VERMELHA (Margem de Segurança Visual)
    const footerExternalArea = 220; // Espaço reservado abaixo da moldura para o rodapé
    ctx.strokeStyle = '#8f1919';
    ctx.lineWidth = 6;
    ctx.strokeRect(60, 60, width - 120, height - footerExternalArea - 60);

    let currentY = 180;

    // Cabeçalho (Título da Categoria)
    ctx.fillStyle = '#8f1919';
    ctx.font = 'bold 110px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(category, width / 2, currentY);
    currentY += 120;

    // Data (se habilitada)
    if (includeDate) {
      const formattedDate = new Date(giftDate).toLocaleDateString('pt-BR');
      ctx.font = 'bold 45px Arial';
      ctx.fillStyle = '#b91c1c';
      ctx.fillText(formattedDate, width / 2, currentY);
      currentY += 120;
    }

    // Conteúdo Principal
    ctx.fillStyle = '#1a1a1a';
    ctx.font = `${drawFontSize}px Arial, "Apple Color Emoji", "Segoe UI Emoji"`;
    ctx.textBaseline = 'top';

    wrappedParagraphs.forEach((lines) => {
      lines.forEach((line, idx) => {
        if (line === "") {
          currentY += lineHeight;
          return;
        }

        const isLastLine = idx === lines.length - 1;

        if (textAlign === 'justify' && !isLastLine) {
          const words = line.split(' ');
          ctx.textAlign = 'left';
          if (words.length > 1) {
            const totalWordsWidth = words.reduce((acc, w) => acc + ctx.measureText(w).width, 0);
            const totalSpacing = maxWidth - totalWordsWidth;
            const spaceWidth = totalSpacing / (words.length - 1);
            let startX = marginX;
            words.forEach((word) => {
              ctx.fillText(word, startX, currentY);
              startX += ctx.measureText(word).width + spaceWidth;
            });
          } else {
            ctx.fillText(line, marginX, currentY);
          }
        } else if (textAlign === 'center') {
          ctx.textAlign = 'center';
          ctx.fillText(line, width / 2, currentY);
        } else {
          ctx.textAlign = 'left';
          ctx.fillText(line, marginX, currentY);
        }
        currentY += lineHeight;
      });
      currentY += lineHeight * 0.4; // Espaço entre parágrafos
    });

    // RODAPÉ (Abaixo da moldura, área limpa)
    const footerY = height - 120;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    // Nome fixo da denominação
    ctx.font = 'bold 36px Arial';
    ctx.fillStyle = '#8f1919';
    ctx.fillText('IGREJA CRISTÃ MARANATA', width / 2, footerY);

    // Nome da igreja local (opcional)
    if (churchName) {
      ctx.font = 'bold 30px Arial';
      ctx.fillStyle = '#b91c1c';
      ctx.fillText(churchName.toUpperCase(), width / 2, footerY + 50);
    }

    setGeneratedImageUrl(canvas.toDataURL('image/png'));
    setIsGenerating(false);
  };

  if (step === 'SELECT') {
    return (
      <div className="min-h-screen bg-[#fff5f5] p-6 flex flex-col items-center animate-fade-in">
        <div className="max-w-md w-full flex flex-col items-center text-center">
          <h1 className="text-4xl font-bold text-[#8f1919] mb-8">Registro de Dons</h1>
          <div className="w-full bg-white rounded-[2rem] shadow-xl p-8 mb-6 border border-red-50">
            <h2 className="text-[#8f1919] font-bold text-xl mb-8 tracking-wider uppercase">O que vamos registrar?</h2>
            <div className="space-y-4">
              {(['SONHO', 'VISÃO', 'REVELAÇÃO', 'OUTROS'] as GiftCategory[]).map((option) => (
                <button
                  key={option}
                  onClick={() => handleSelectCategory(option)}
                  className="w-full py-5 rounded-2xl border border-red-200 text-[#8f1919] font-bold text-xl hover:bg-red-50 active:scale-95 transition-all"
                >
                  {option}
                </button>
              ))}
            </div>
          </div>
          <button onClick={onBack} className="w-full bg-white border border-red-400 text-red-600 font-bold py-4 rounded-2xl shadow-md flex items-center justify-center gap-2">
            <i className="fas fa-arrow-left"></i> Voltar ao Início
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#fff5f5] p-4 flex flex-col items-center animate-fade-in">
      <div className="max-w-lg w-full">
        <h1 className="text-3xl font-bold text-[#8f1919] mb-6 text-center">Registro de Dons</h1>

        <div className="bg-white rounded-[2rem] shadow-xl p-6 mb-6 border border-red-50 flex flex-col">
          <div className="flex justify-center mb-6">
            <button className="px-10 py-2 border-2 border-red-200 rounded-xl text-[#8f1919] font-bold text-xl uppercase bg-white">
              {category}
            </button>
          </div>

          <div className="space-y-5">
            <div>
              <label className="text-[10px] font-bold text-red-700 uppercase ml-1 block mb-1">Igreja / Localidade:</label>
              <input 
                type="text" 
                placeholder="Ex: Planalto Linhares - ES"
                value={churchName}
                onChange={(e) => setChurchName(e.target.value)}
                className="w-full border border-red-200 rounded-xl p-3 text-sm focus:ring-2 focus:ring-red-100 outline-none bg-white text-slate-800"
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
               <div className="flex flex-col gap-2">
                 <label className="text-[10px] font-bold text-red-700 uppercase ml-1">Data:</label>
                 <input type="date" value={giftDate} onChange={(e) => setGiftDate(e.target.value)} className="w-full border border-red-200 rounded-xl p-3 text-xs outline-none bg-white" />
               </div>
               <div className="flex flex-col gap-2 justify-end pb-2">
                  <label className="flex items-center gap-2 text-[11px] font-bold text-red-700 cursor-pointer">
                    <input type="checkbox" checked={includeDate} onChange={(e) => setIncludeDate(e.target.checked)} className="w-4 h-4 accent-red-600" />
                    Mostrar Data
                  </label>
               </div>
            </div>

            <div className="border-t border-red-50 pt-4">
              <label className="text-[10px] font-bold text-red-700 uppercase ml-1 block mb-2">Formato da Imagem:</label>
              <div className="flex gap-2 mb-4">
                 <button 
                  onClick={() => { setIsVertical(true); setGeneratedImageUrl(null); }}
                  className={`flex-1 py-3 rounded-lg text-[10px] font-bold border transition-all flex flex-col items-center gap-1 ${isVertical ? 'bg-red-600 text-white border-red-600 shadow-md' : 'bg-white text-red-600 border-red-200'}`}
                 >
                   <i className="fas fa-mobile-alt text-lg"></i>
                   EM PÉ (VERTICAL)
                 </button>
                 <button 
                  onClick={() => { setIsVertical(false); setGeneratedImageUrl(null); }}
                  className={`flex-1 py-3 rounded-lg text-[10px] font-bold border transition-all flex flex-col items-center gap-1 ${!isVertical ? 'bg-red-600 text-white border-red-600 shadow-md' : 'bg-white text-red-600 border-red-200'}`}
                 >
                   <i className="fas fa-image text-lg"></i>
                   DEITADA (HORIZONTAL)
                 </button>
              </div>

              <label className="text-[10px] font-bold text-red-700 uppercase ml-1 block mb-2">Alinhamento:</label>
              <div className="flex gap-2">
                 {(['left', 'center', 'justify'] as TextAlign[]).map((align) => (
                   <button 
                    key={align}
                    onClick={() => { setTextAlign(align); setGeneratedImageUrl(null); }}
                    className={`flex-1 py-3 rounded-lg text-xl border transition-all ${textAlign === align ? 'bg-red-100 text-red-700 border-red-300' : 'bg-white text-gray-400 border-gray-100'}`}
                   >
                     <i className={`fas fa-align-${align === 'justify' ? 'justify' : align}`}></i>
                   </button>
                 ))}
              </div>
            </div>

            <div className="flex items-center justify-between px-2 pt-2">
              <span className="text-[10px] font-bold text-red-700 uppercase">Tamanho da Letra:</span>
              <div className="flex items-center gap-3">
                <button onClick={() => setFontSize(f => Math.max(12, f - 2))} className="w-8 h-8 rounded-full bg-red-50 text-red-700 flex items-center justify-center font-bold shadow-sm">-</button>
                <span className="font-bold text-red-900 text-base">{fontSize}</span>
                <button onClick={() => setFontSize(f => Math.min(60, f + 2))} className="w-8 h-8 rounded-full bg-red-50 text-red-700 flex items-center justify-center font-bold shadow-sm">+</button>
              </div>
            </div>

            <div className="relative">
              <textarea 
                placeholder={`Descreva aqui o ${category.toLowerCase()}...`}
