export default GiftRegistration;

import React, { useState, useEffect, useRef } from 'react';

interface GiftRegistrationProps {
  onBack: () => void;
}

type GiftCategory = 'SONHO' | 'VISÃO' | 'REVELAÇÃO' | 'OUTROS';
type TextAlign = 'left' | 'center' | 'justify';

const GiftRegistration: React.FC<GiftRegistrationProps> = ({ onBack }) => {
  const [step, setStep] = useState<'SELECT' | 'EDIT'>('SELECT');
  const [category, setCategory] = useState<GiftCategory>('SONHO');
  const [churchName, setChurchName] = useState('');
  const [includeDate, setIncludeDate] = useState(true);
  const [giftDate, setGiftDate] = useState(new Date().toISOString().split('T')[0]);
  const [isVertical, setIsVertical] = useState(true);
  const [textAlign, setTextAlign] = useState<TextAlign>('left');
  const [fontSize, setFontSize] = useState(24);
  const [content, setContent] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [generatedImageUrl, setGeneratedImageUrl] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.continuous = true;
      recognition.interimResults = true;
      recognition.lang = 'pt-BR';
      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);
      recognition.onresult = (event: any) => {
        let transcript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) transcript += event.results[i][0].transcript;
        }
        if (transcript) setContent(prev => prev + (prev ? ' ' : '') + transcript);
      };
      recognitionRef.current = recognition;
    }
  }, []);

  const toggleListening = () => {
    if (!recognitionRef.current) return alert("Microfone não suportado.");
    isListening ? recognitionRef.current.stop() : recognitionRef.current.start();
  };

  const generateGiftImage = async () => {
    setIsGenerating(true);
    await new Promise(r => setTimeout(r, 600));

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Configurações de Dimensão (High Definition)
    const width = isVertical ? 1080 : 1920;
    const baseMinHeight = isVertical ? 1920 : 1080;

    // Margens e Espaçamentos
    const marginX = 160; 
    const headerH = 450;
    const footerH = 350; // Espaço para o rodapé fora da moldura
    const maxWidth = width - (marginX * 2);

    const drawFontSize = fontSize * 2.2;
    const lineHeight = drawFontSize * 1.5;
    ctx.font = `${drawFontSize}px Arial, "Apple Color Emoji", "Segoe UI Emoji"`;

    // Processamento de Quebra de Linha (Word Wrap)
    const paragraphs = content.split('\n');
    const wrappedLines: { text: string; isLastInPara: boolean }[] = [];

    paragraphs.forEach(p => {
      if (p.trim() === "") {
        wrappedLines.push({ text: "", isLastInPara: true });
        return;
      }
      const words = p.split(' ');
      let currentLine = "";
      for (let n = 0; n < words.length; n++) {
        const testLine = currentLine + words[n] + " ";
        const metrics = ctx.measureText(testLine);
        if (metrics.width > maxWidth && n > 0) {
          wrappedLines.push({ text: currentLine.trim(), isLastInPara: false });
          currentLine = words[n] + " ";
        } else {
          currentLine = testLine;
        }
      }
      wrappedLines.push({ text: currentLine.trim(), isLastInPara: true });
    });

    // Calcula Altura Final Necessária
    const totalLinesHeight = wrappedLines.length * lineHeight;
    const requiredHeight = headerH + totalLinesHeight + footerH;
    const height = Math.max(baseMinHeight, requiredHeight);

    canvas.width = width;
    canvas.height = height;

    // 1. Fundo
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, width, height);

    // 2. Moldura Vermelha (Deixa o rodapé de fora)
    const borderBottomMargin = 220; // Espaço para rodapé
    ctx.strokeStyle = '#8f1919';
    ctx.lineWidth = 8;
    ctx.strokeRect(60, 60, width - 120, height - borderBottomMargin - 60);

    // 3. Cabeçalho
    let currentY = 180;
    ctx.fillStyle = '#8f1919';
    ctx.font = 'bold 110px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(category, width / 2, currentY);

    if (includeDate) {
      currentY += 120;
      ctx.font = 'bold 45px Arial';
      ctx.fillStyle = '#b91c1c';
      const formattedDate = new Date(giftDate).toLocaleDateString('pt-BR');
      ctx.fillText(formattedDate, width / 2, currentY);
    }

    // 4. Texto Principal (Conteúdo)
    currentY += 150;
    ctx.textBaseline = 'top';
    ctx.font = `${drawFontSize}px Arial, "Apple Color Emoji", "Segoe UI Emoji"`;

    wrappedLines.forEach((lineObj) => {
      if (lineObj.text === "") {
        currentY += lineHeight;
        return;
      }

      if (textAlign === 'justify' && !lineObj.isLastInPara) {
        const words = lineObj.text.split(' ');
        ctx.textAlign = 'left';
        if (words.length > 1) {
          const wordsTotalWidth = words.reduce((acc, w) => acc + ctx.measureText(w).width, 0);
          const spaceW = (maxWidth - wordsTotalWidth) / (words.length - 1);
          let startX = marginX;
          words.forEach(word => {
            ctx.fillText(word, startX, currentY);
            startX += ctx.measureText(word).width + spaceW;
          });
        } else {
          ctx.fillText(lineObj.text, marginX, currentY);
        }
      } else if (textAlign === 'center') {
        ctx.textAlign = 'center';
        ctx.fillText(lineObj.text, width / 2, currentY);
      } else {
        ctx.textAlign = 'left';
        ctx.fillText(lineObj.text, marginX, currentY);
      }
      currentY += lineHeight;
    });

    // 5. Rodapé Externo (Abaixo da moldura)
    const rodapéY = height - 120;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = '#8f1919';
    ctx.font = 'bold 36px Arial';
    ctx.fillText('IGREJA CRISTÃ MARANATA', width / 2, rodapéY);

    if (churchName) {
      ctx.fillStyle = '#b91c1c';
      ctx.font = 'bold 30px Arial';
      ctx.fillText(churchName.toUpperCase(), width / 2, rodapéY + 55);
    }

    setGeneratedImageUrl(canvas.toDataURL('image/png'));
    setIsGenerating(false);
  };

  if (step === 'SELECT') {
    return (
      <div className="min-h-screen bg-[#fff5f5] p-6 flex flex-col items-center animate-fade-in">
        <div className="max-w-md w-full flex flex-col items-center text-center">
          <h1 className="text-4xl font-bold text-[#8f1919] mb-8 uppercase tracking-tighter">Registro de Dons</h1>
          <div className="w-full bg-white rounded-[2rem] shadow-xl p-8 mb-6 border border-red-50">
            <h2 className="text-[#8f1919] font-bold text-xl mb-8 uppercase tracking-widest">Categoria</h2>
            <div className="space-y-4">
              {(['SONHO', 'VISÃO', 'REVELAÇÃO', 'OUTROS'] as GiftCategory[]).map((option) => (
                <button
                  key={option}
                  onClick={() => { setCategory(option); setStep('EDIT'); }}
                  className="w-full py-5 rounded-2xl border border-red-200 text-[#8f1919] font-bold text-xl hover:bg-red-50 active:scale-95 transition-all"
                >
                  {option}
                </button>
              ))}
            </div>
          </div>
          <button onClick={onBack} className="w-full bg-white border border-red-400 text-red-600 font-bold py-4 rounded-2xl shadow-md">
            <i className="fas fa-arrow-left mr-2"></i> Voltar
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#fff5f5] p-4 flex flex-col items-center animate-fade-in">
      <div className="max-w-lg w-full">
        <div className="bg-white rounded-[2rem] shadow-xl p-6 mb-6 border border-red-50">
          <div className="flex justify-between items-center mb-6">
            <button onClick={() => setStep('SELECT')} className="text-red-600 font-bold text-sm">
              <i className="fas fa-chevron-left mr-1"></i> TROCAR
            </button>
            <span className="bg-red-50 text-[#8f1919] px-6 py-1 rounded-full font-black tracking-widest uppercase">{category}</span>
            <div className="w-10"></div>
          </div>

          <div className="space-y-4">
            <input 
              type="text" 
              placeholder="IGREJA / LOCALIDADE (OPCIONAL)"
              value={churchName}
              onChange={(e) => setChurchName(e.target.value.toUpperCase())}
              className="w-full border border-red-100 rounded-xl p-4 text-sm font-bold bg-red-50/30 outline-none focus:ring-2 focus:ring-red-200"
            />

            <div className="flex gap-2">
              <input type="date" value={giftDate} onChange={(e) => setGiftDate(e.target.value)} className="flex-1 border border-red-100 rounded-xl p-3 text-sm outline-none font-bold" />
              <button 
                onClick={() => setIncludeDate(!includeDate)}
                className={`px-4 rounded-xl border font-bold text-[10px] transition-all ${includeDate ? 'bg-red-600 text-white border-red-600' : 'bg-white text-red-400 border-red-100'}`}
              >
                {includeDate ? 'DATA ON' : 'DATA OFF'}
              </button>
            </div>

            <div className="grid grid-cols-2 gap-2 pt-2">
              <button 
                onClick={() => { setIsVertical(true); setGeneratedImageUrl(null); }}
                className={`py-3 rounded-xl border flex flex-col items-center gap-1 font-black text-[10px] transition-all ${isVertical ? 'bg-red-600 text-white border-red-600 shadow-lg' : 'bg-white text-red-300 border-red-50'}`}
              >
                <i className="fas fa-mobile-alt text-lg"></i> EM PÉ
              </button>
              <button 
                onClick={() => { setIsVertical(false); setGeneratedImageUrl(null); }}
                className={`py-3 rounded-xl border flex flex-col items-center gap-1 font-black text-[10px] transition-all ${!isVertical ? 'bg-red-600 text-white border-red-600 shadow-lg' : 'bg-white text-red-300 border-red-50'}`}
              >
                <i className="fas fa-image text-lg"></i> DEITADA
              </button>
            </div>

            <div className="flex gap-2 py-1">
              {(['left', 'center', 'justify'] as TextAlign[]).map((align) => (
                <button 
                  key={align}
                  onClick={() => { setTextAlign(align); setGeneratedImageUrl(null); }}
                  className={`flex-1 py-3 rounded-xl border text-xl transition-all ${textAlign === align ? 'bg-red-100 text-red-700 border-red-300 shadow-inner' : 'bg-white text-gray-300 border-red-50'}`}
                >
                  <i className={`fas fa-align-${align === 'justify' ? 'justify' : align}`}></i>
                </button>
              ))}
            </div>

            <div className="flex items-center justify-between bg-red-50/50 p-3 rounded-xl">
              <span className="text-[10px] font-bold text-red-800 uppercase">Tamanho da Letra</span>
              <div className="flex items-center gap-4">
                <button onClick={() => setFontSize(f => Math.max(12, f - 2))} className="w-8 h-8 rounded-full bg-white text-red-600 font-bold shadow-sm">-</button>
                <span className="font-black text-red-900">{fontSize}</span>
                <button onClick={() => setFontSize(f => Math.min(60, f + 2))} className="w-8 h-8 rounded-full bg-white text-red-600 font-bold shadow-sm">+</button>
              </div>
            </div>

            <div className="relative mt-2">
              <textarea 
                placeholder="DIGITE O CONTEÚDO DO DOM AQUI..."
                value={content}
                onChange={(e) => { setContent(e.target.value); setGeneratedImageUrl(null); }}
                className={`w-full min-h-[300px] border border-red-100 rounded-2xl p-6 focus:ring-4 focus:ring-red-50 outline-none bg-red-50/10 text-slate-800 leading-relaxed font-medium shadow-inner ${textAlign === 'center' ? 'text-center' : (textAlign === 'justify' ? 'text-justify' : 'text-left')}`}
                style={{ fontSize: `${fontSize}px` }}
              />
              <button 
                onClick={toggleListening}
                className={`absolute bottom-4 right-4 w-14 h-14 rounded-full shadow-2xl flex items-center justify-center transition-all ${isListening ? 'bg-red-600 text-white animate-pulse' : 'bg-white text-red-600 hover:bg-red-50 border border-red-100'}`}
              >
                <i className={`fas ${isListening ? 'fa-stop' : 'fa-microphone'} text-2xl`}></i>
              </button>
            </div>
          </div>
        </div>

        <div className="space-y-4 mb-20">
          <button 
            onClick={generateGiftImage}
            disabled={!content || isGenerating}
            className="w-full bg-[#8f1919] hover:bg-black text-white font-black py-5 rounded-2xl shadow-2xl flex items-center justify-center gap-3 transition-all disabled:opacity-50 text-xl tracking-widest"
          >
            {isGenerating ? <i className="fas fa-spinner animate-spin"></i> : <i className="fas fa-magic"></i>}
            GERAR IMAGEM
          </button>

          {generatedImageUrl && (
            <div className="bg-white rounded-[2rem] shadow-2xl p-6 border-2 border-red-50 animate-fade-in">
              <h3 className="text-[#8f1919] font-black text-center mb-6 uppercase tracking-tighter">Resultado</h3>
              <div className="rounded-2xl overflow-hidden border-4 border-red-50 shadow-inner bg-gray-50 mb-6">
                <img src={generatedImageUrl} alt="Preview" className="w-full h-auto" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <button 
                  onClick={async () => {
                    const res = await fetch(generatedImageUrl);
                    const blob = await res.blob();
                    const file = new File([blob], "dom_icm.png", { type: "image/png" });
                    if (navigator.share) await navigator.share({ files: [file], title: 'Registro de Dom' });
                  }}
                  className="bg-[#25d366] text-white font-black py-4 rounded-xl shadow-lg flex items-center justify-center gap-2 active:scale-95"
                >
                  <i className="fab fa-whatsapp text-2xl"></i> WHATSAPP
                </button>
                <button 
                  onClick={() => {
                    const link = document.createElement('a');
                    link.download = `dom_icm_${category.toLowerCase()}.png`;
                    link.href = generatedImageUrl;
                    link.click();
                  }}
                  className="bg-blue-600 text-white font-black py-4 rounded-xl shadow-lg flex items-center justify-center gap-2 active:scale-95"
                >
                  <i className="fas fa-download"></i> BAIXAR
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

