      ctx.fillStyle = '#b91c1c';
      const formattedDate = new Date(giftDate).toLocaleDateString('pt-BR');
      ctx.fillText(formattedDate, width / 2, currentY);
    }

    // Main Content
    currentY += 150;
    ctx.textBaseline = 'top';
    ctx.font = `${drawFontSize}px Arial, "Apple Color Emoji", "Segoe UI Emoji"`;
    ctx.fillStyle = '#1a1a1a';

