              <div className="flex items-center gap-4">
                <button onClick={() => { setFontSize(f => Math.max(12, f - 2)); setGeneratedImageUrl(null); }} className="w-8 h-8 rounded-full bg-white text-red-600 font-bold shadow-sm border border-red-100">-</button>
                <span className="font-black text-red-900 w-6 text-center">{fontSize}</span>
                <button onClick={() => { setFontSize(f => Math.min(60, f + 2)); setGeneratedImageUrl(null); }} className="w-8 h-8 rounded-full bg-white text-red-600 font-bold shadow-sm border border-red-100">+</button>
