                className={`w-full min-h-[320px] border-2 border-red-50 rounded-2xl p-6 focus:ring-4 focus:ring-red-100 outline-none bg-red-50/10 text-slate-800 leading-relaxed font-semibold shadow-inner ${textAlign === 'center' ? 'text-center' : (textAlign === 'justify' ? 'text-justify' : 'text-left')}`}
                style={{ fontSize: `${fontSize}px` }}
              />
              <button 
                onClick={toggleListening}
                className={`absolute bottom-4 right-4 w-14 h-14 rounded-full shadow-2xl flex items-center justify-center transition-all ${isListening ? 'bg-red-600 text-white animate-pulse' : 'bg-white text-red-600 hover:bg-red-50 border-2 border-red-100'}`}
              >
                <i className={`fas ${isListening ? 'fa-stop' : 'fa-microphone'} text-2xl`}></i>
              </button>
            </div>
          </div>
        </div>

        <div className="space-y-4 mb-20">
          <button 
