export default GiftRegistration;

import React, { useState, useEffect, useRef } from 'react';

interface GiftRegistrationProps {
  onBack: () => void;
}

type GiftCategory = 'SONHO' | 'VISÃO' | 'REVELAÇÃO' | 'OUTROS';
type TextAlign = 'left' | 'center' | 'justify';

const GiftRegistration: React.FC<GiftRegistrationProps> = ({ onBack }) => {
  const [step, setStep] = useState<'SELECT' | 'EDIT'>('SELECT');
  const [category, setCategory] = useState<GiftCategory>('SONHO');
  const [customCategory, setCustomCategory] = useState('');
  const [churchName, setChurchName] = useState('');
  const [includeDate, setIncludeDate] = useState(true);
  const [giftDate, setGiftDate] = useState(new Date().toISOString().split('T')[0]);
  const [isVertical, setIsVertical] = useState(true);
  const [textAlign, setTextAlign] = useState<TextAlign>('left');
  const [fontSize, setFontSize] = useState(24);
  const [content, setContent] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [generatedImageUrl, setGeneratedImageUrl] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.continuous = true;
      recognition.interimResults = true;
      recognition.lang = 'pt-BR';
      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => setIsListening(false);
      recognition.onresult = (event: any) => {
        let transcript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) transcript += event.results[i][0].transcript;
        }
        if (transcript) setContent(prev => prev + (prev ? ' ' : '') + transcript);
      };
      recognitionRef.current = recognition;
    }
  }, []);

  const toggleListening = () => {
    if (!recognitionRef.current) return alert("Microfone não suportado.");
    isListening ? recognitionRef.current.stop() : (setContent(''), recognitionRef.current.start());
  };

  const generateGiftImage = async () => {
    setIsGenerating(true);
    await new Promise(r => setTimeout(r, 800));

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const baseWidth = isVertical ? 1080 : 1920;
    const baseMinHeight = isVertical ? 1920 : 1080;
    const marginX = 160; 
    const headerH = 480;
    const footerSafeZone = 350;
    const maxWidth = baseWidth - (marginX * 2);

    const drawFontSize = fontSize * 2.2;
    const lineHeight = drawFontSize * 1.5;
    ctx.font = `${drawFontSize}px Arial, "Apple Color Emoji", "Segoe UI Emoji"`;

    const paragraphs = content.split('\n');
    const wrappedLines: { text: string; isLastInPara: boolean }[] = [];

    paragraphs.forEach(p => {
      if (p.trim() === "") {
        wrappedLines.push({ text: "", isLastInPara: true });
        return;
      }
      const words = p.split(' ');
      let currentLine = "";
      for (let n = 0; n < words.length; n++) {
        const testLine = currentLine + words[n] + " ";
        if (ctx.measureText(testLine).width > maxWidth && n > 0) {
          wrappedLines.push({ text: currentLine.trim(), isLastInPara: false });
          currentLine = words[n] + " ";
        } else {
          currentLine = testLine;
        }
      }
      wrappedLines.push({ text: currentLine.trim(), isLastInPara: true });
    });

    const calculatedHeight = headerH + (wrappedLines.length * lineHeight) + footerSafeZone;
    const height = Math.max(baseMinHeight, calculatedHeight);
    const width = baseWidth;

    canvas.width = width;
    canvas.height = height;

    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, width, height);

    const frameBottomMargin = 220; 
    ctx.strokeStyle = '#8f1919';
    ctx.lineWidth = 12;
    ctx.strokeRect(60, 60, width - 120, height - frameBottomMargin - 60);

    let currentY = 200;
    ctx.fillStyle = '#8f1919';
    ctx.font = 'bold 120px Arial';
    ctx.textAlign = 'center';
    const displayCategory = category === 'OUTROS' ? (customCategory || 'REGISTRO') : category;
    ctx.fillText(displayCategory.toUpperCase(), width / 2, currentY);

    if (includeDate) {
      currentY += 130;
      ctx.font = 'bold 48px Arial';
      ctx.fillStyle = '#b91c1c';
      ctx.fillText(new Date(giftDate).toLocaleDateString('pt-BR'), width / 2, currentY);
    }

    currentY += 160;
    ctx.textBaseline = 'top';
    ctx.font = `${drawFontSize}px Arial`;
    ctx.fillStyle = '#1a1a1a';

    wrappedLines.forEach((lineObj) => {
      if (lineObj.text === "") {
        currentY += lineHeight;
        return;
      }

      if (textAlign === 'justify' && !lineObj.isLastInPara) {
        const words = lineObj.text.split(' ');
        ctx.textAlign = 'left';
        if (words.length > 1) {
          const wordsW = words.reduce((acc, w) => acc + ctx.measureText(w).width, 0);
          const spaceW = (maxWidth - wordsW) / (words.length - 1);
          let startX = marginX;
          words.forEach(word => {
            ctx.fillText(word, startX, currentY);
            startX += ctx.measureText(word).width + spaceW;
          });
        } else {
          ctx.fillText(lineObj.text, marginX, currentY);
        }
      } else if (textAlign === 'center') {
        ctx.textAlign = 'center';
        ctx.fillText(lineObj.text, width / 2, currentY);
      } else {
        ctx.textAlign = 'left';
        ctx.fillText(lineObj.text, marginX, currentY);
      }
      currentY += lineHeight;
    });

    const footY = height - 120;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = '#8f1919';
    ctx.font = 'bold 38px Arial';
    ctx.fillText('IGREJA CRISTÃ MARANATA', width / 2, footY);
    if (churchName) {
      ctx.fillStyle = '#b91c1c';
      ctx.font = 'bold 32px Arial';
      ctx.fillText(churchName.toUpperCase(), width / 2, footY + 65);
    }

    setGeneratedImageUrl(canvas.toDataURL('image/png'));
    setIsGenerating(false);
  };

  if (step === 'SELECT') {
    return (
      <div className="min-h-screen bg-[#fff5f5] p-6 flex flex-col items-center animate-fade-in">
        <div className="max-w-md w-full flex flex-col items-center">
          <header className="text-center mb-10 pt-4">
            <h1 className="text-4xl font-black text-[#8f1919] uppercase tracking-tighter">Registro de Dons</h1>
            <p className="text-red-400 font-bold text-sm mt-2 tracking-widest uppercase">Igreja Cristã Maranata</p>
          </header>

          <div className="w-full bg-white rounded-[2.5rem] shadow-2xl p-8 border border-red-50 flex flex-col gap-4">
            <h2 className="text-[#8f1919] font-black text-center mb-4 uppercase tracking-widest text-lg">O que deseja registrar?</h2>
            {(['SONHO', 'VISÃO', 'REVELAÇÃO', 'OUTROS'] as GiftCategory[]).map((option) => (
              <button
                key={option}
                onClick={() => { setCategory(option); setStep('EDIT'); }}
                className="w-full py-6 rounded-2xl border-2 border-red-50 text-[#8f1919] font-black text-xl hover:bg-[#8f1919] hover:text-white hover:border-[#8f1919] active:scale-95 transition-all shadow-sm flex items-center justify-center gap-3 group"
              >
                <i className={`fas ${option === 'SONHO' ? 'fa-cloud' : option === 'VISÃO' ? 'fa-eye' : option === 'REVELAÇÃO' ? 'fa-bolt' : 'fa-plus-circle'} opacity-20 group-hover:opacity-100 transition-opacity`}></i>
                {option}
              </button>
            ))}
          </div>

          <button onClick={onBack} className="mt-8 text-red-600 font-bold uppercase tracking-widest text-xs flex items-center gap-2">
            <i className="fas fa-arrow-left"></i> Voltar ao Menu
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#fff5f5] p-4 pb-20 flex flex-col items-center animate-fade-in">
      <div className="max-w-lg w-full">
        <header className="flex items-center justify-between mb-6 px-2">
          <button onClick={() => setStep('SELECT')} className="text-red-600 font-black text-xs uppercase bg-white px-4 py-2 rounded-full shadow-sm">
            <i className="fas fa-chevron-left mr-1"></i> Categorias
          </button>
          <h2 className="text-xl font-black text-[#8f1919] uppercase tracking-tighter">Editor de Registro</h2>
          <div className="w-20"></div>
        </header>

        <div className="bg-white rounded-[2.5rem] shadow-2xl p-6 border border-red-50 space-y-6">
          <div className="flex justify-center -mt-10 mb-4">
             <div className="bg-[#8f1919] text-white px-10 py-3 rounded-2xl font-black tracking-widest text-lg shadow-xl uppercase border-4 border-white">
                {category}
             </div>
          </div>

          <div className="space-y-4">
            {category === 'OUTROS' && (
              <div className="bg-red-50/50 p-4 rounded-2xl border border-red-100 animate-fade-in">
                <label className="text-[10px] font-black text-red-800 uppercase ml-1 block mb-2">Qual o título deste registro?</label>
                <input 
                  type="text" 
                  placeholder="EX: BATISMO, REUNIÃO, CULTO INFANTIL..."
                  value={customCategory}
                  onChange={(e) => { setCustomCategory(e.target.value.toUpperCase()); setGeneratedImageUrl(null); }}
                  className="w-full border-2 border-white rounded-xl p-4 text-sm font-black bg-white outline-none focus:border-red-600 shadow-sm"
                />
              </div>
            )}

            <div>
              <label className="text-[10px] font-black text-red-800 uppercase ml-1 block mb-1">Localidade / Igreja (Opcional):</label>
              <input 
                type="text" 
                placeholder="EX: PLANALTO LINHARES - ES"
                value={churchName}
                onChange={(e) => { setChurchName(e.target.value.toUpperCase()); setGeneratedImageUrl(null); }}
                className="w-full border-2 border-red-50 rounded-xl p-4 text-sm font-bold bg-red-50/20 outline-none focus:border-red-200"
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="flex flex-col gap-1">
                <label className="text-[10px] font-black text-red-800 uppercase ml-1">Data:</label>
                <input type="date" value={giftDate} onChange={(e) => { setGiftDate(e.target.value); setGeneratedImageUrl(null); }} className="w-full border-2 border-red-50 rounded-xl p-3 text-sm font-bold outline-none" />
              </div>
              <div className="flex flex-col justify-end gap-1">
                <button 
                  onClick={() => { setIncludeDate(!includeDate); setGeneratedImageUrl(null); }}
                  className={`w-full py-3.5 rounded-xl border-2 font-black text-[10px] transition-all flex items-center justify-center gap-2 ${includeDate ? 'bg-red-600 text-white border-red-600' : 'bg-white text-red-300 border-red-50'}`}
                >
                  <i className={`fas ${includeDate ? 'fa-calendar-check' : 'fa-calendar-times'}`}></i>
                  {includeDate ? 'MOSTRAR DATA' : 'OCULTAR DATA'}
                </button>
              </div>
            </div>

            <div className="pt-4 border-t border-red-50">
               <label className="text-[10px] font-black text-red-800 uppercase ml-1 block mb-3">Estilo da Imagem:</label>
               <div className="grid grid-cols-2 gap-3">
                  <button 
                    onClick={() => { setIsVertical(true); setGeneratedImageUrl(null); }}
                    className={`py-4 rounded-xl border-2 flex flex-col items-center gap-2 font-black text-[10px] transition-all ${isVertical ? 'bg-red-600 text-white border-red-600 shadow-md' : 'bg-white text-red-200 border-red-50'}`}
                  >
                    <i className="fas fa-mobile-alt text-xl"></i> VERTICAL
                  </button>
                  <button 
                    onClick={() => { setIsVertical(false); setGeneratedImageUrl(null); }}
                    className={`py-4 rounded-xl border-2 flex flex-col items-center gap-2 font-black text-[10px] transition-all ${!isVertical ? 'bg-red-600 text-white border-red-600 shadow-md' : 'bg-white text-red-200 border-red-50'}`}
                  >
                    <i className="fas fa-image text-xl"></i> HORIZONTAL
                  </button>
               </div>
            </div>

            <div className="flex gap-2">
              {(['left', 'center', 'justify'] as TextAlign[]).map((align) => (
                <button 
                  key={align}
                  onClick={() => { setTextAlign(align); setGeneratedImageUrl(null); }}
                  className={`flex-1 py-4 rounded-xl border-2 text-xl transition-all flex items-center justify-center ${textAlign === align ? 'bg-red-100 text-red-700 border-red-300' : 'bg-white text-gray-200 border-red-50'}`}
                >
                  <i className={`fas fa-align-${align === 'justify' ? 'justify' : align}`}></i>
                </button>
              ))}
            </div>

            <div className="flex items-center justify-between bg-red-50/50 p-4 rounded-2xl border border-red-100">
              <span className="text-xs font-black text-red-900 uppercase">Tamanho da Letra</span>
              <div className="flex items-center gap-5">
                <button onClick={() => { setFontSize(f => Math.max(12, f - 2)); setGeneratedImageUrl(null); }} className="w-10 h-10 rounded-full bg-white text-red-600 font-bold shadow-sm border-2 border-red-100 flex items-center justify-center">-</button>
                <span className="font-black text-red-900 text-xl">{fontSize}</span>
                <button onClick={() => { setFontSize(f => Math.min(60, f + 2)); setGeneratedImageUrl(null); }} className="w-10 h-10 rounded-full bg-white text-red-600 font-bold shadow-sm border-2 border-red-100 flex items-center justify-center">+</button>
              </div>
            </div>

            <div className="relative pt-2">
              <textarea 
                placeholder={`ESCREVA AQUI O ${category.toUpperCase()}...`}
                value={content}
                onChange={(e) => { setContent(e.target.value); setGeneratedImageUrl(null); }}
                className={`w-full min-h-[350px] border-2 border-red-50 rounded-[2rem] p-8 focus:ring-8 focus:ring-red-50/50 outline-none bg-red-50/20 text-slate-800 leading-relaxed font-semibold shadow-inner transition-all ${textAlign === 'center' ? 'text-center' : (textAlign === 'justify' ? 'text-justify' : 'text-left')}`}
                style={{ fontSize: `${fontSize}px` }}
              />
              <button 
                onClick={toggleListening}
                className={`absolute bottom-6 right-6 w-16 h-16 rounded-full shadow-2xl flex items-center justify-center transition-all ${isListening ? 'bg-red-600 text-white animate-pulse' : 'bg-white text-red-600 hover:bg-red-50 border-2 border-red-100'}`}
              >
                <i className={`fas ${isListening ? 'fa-stop' : 'fa-microphone'} text-2xl`}></i>
              </button>
            </div>
          </div>
        </div>

        <div className="mt-8 space-y-4">
