                  className="bg-[#25d366] text-white font-black py-5 rounded-2xl shadow-lg flex items-center justify-center gap-3 active:scale-95 transition-all text-sm"
                >
                  <i className="fab fa-whatsapp text-2xl"></i> WHATSAPP
                </button>
                <button 
                  onClick={() => {
